/** 自动加点：加点界面做好前的旧档公式，仅用于迁移种子；UI-6 起升级只发未分配点。 */
export const AUTO_STATS = { rootBone: 2, agility: 2, insight: 1, spirit: 0 } as Record<string, number>;
export const STAT_KEYS = Object.freeze(['rootBone', 'agility', 'spirit', 'insight'] as const);
export type StatKey = typeof STAT_KEYS[number];
export type AllocateCheck = { ok: true } | { ok: false; reason: 'invalid' | 'overspend' };
export type AllocateResult = AllocateCheck | { ok: false; reason: 'save' };
/** 已结算的普通任务奖励；场景仅用来显示日志和刷新外观。 */
export interface QuestRewardSettlement {
  exp: ReturnType<Progress['gainExp']>;
  items: { item: string; count: number; equipped?: boolean }[];
  skills: string[];
}
export const EQUIP_SLOTS = Object.freeze(['weapon', 'robe', 'shoes'] as const);
export type EquipSlot = typeof EQUIP_SLOTS[number];
export type EquipResult = { ok: true } | { ok: false; reason: 'invalid' | 'missing' | 'sect' | 'level' | 'empty' | 'overflow' | 'save' };
const SAVE_KEY = 'xiantu_save_v1';
/** 保留关系结构首次迁移前的原档，便于人工恢复；不覆盖已有备份。 */
export const RELATIONSHIP_BACKUP_KEY = 'xiantu_save_relationship_v1_backup';
/** 妖狐任务改为五宗帖的奖励版本；无此字段的已交付旧档保留原天剑身份。 */
const QUEST_REWARD_VERSION = 1;
/** 道心与善恶存档版本；旧档只补缺失初值，不推断历史选择。 */
export const MORAL_VERSION = 1;
export interface SavePosition { mapId: string; x: number; y: number }
export interface SectTrialAttempt { id: string; returnPosition: SavePosition }
const flagKey = (key: string) => typeof key === 'string' && /^[a-zA-Z][\w.-]*$/.test(key)
  && !key.split('.').some(part => ['__proto__', 'prototype', 'constructor'].includes(part));
const dataRecord = (value: unknown): value is Record<string, unknown> => !!value && typeof value === 'object' && !Array.isArray(value);
const safeKey = (key: string) => !['__proto__', 'prototype', 'constructor'].includes(key);
const nonnegative = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value) && value >= 0;
const count = (value: unknown): value is number => nonnegative(value) && Number.isSafeInteger(value);
const statKey = (key: string): key is StatKey => STAT_KEYS.some(k => k === key);
const statRecord = (value: unknown): value is Record<string, number> => dataRecord(value)
  && [Object.prototype, null].includes(Object.getPrototypeOf(value))
  && Reflect.ownKeys(value).every(key => typeof key === 'string' && statKey(key)
    && count(Object.getOwnPropertyDescriptor(value, key)?.value));
const normalizedStats = (value: unknown): Record<string, number> => Object.fromEntries(STAT_KEYS.map(key => {
  const n = dataRecord(value) ? Object.getOwnPropertyDescriptor(value, key)?.value : undefined;
  return [key, count(n) ? n : 0];
}));
const numbers = (value: unknown, integer = true) => dataRecord(value)
  && Object.entries(value).every(([key, n]) => safeKey(key) && (integer ? count(n) : nonnegative(n)));
const strings = (value: unknown) => Array.isArray(value) && value.every(entry => typeof entry === 'string');

/** 导入允许旧档缺字段；已有核心状态必须可安全参与当前游戏计算。 */
function validSaveData(saved: unknown): saved is Record<string, unknown> {
  if (!dataRecord(saved)) return false;
  const has = (key: string) => Object.prototype.hasOwnProperty.call(saved, key);
  if (has('level') && (!count(saved.level) || saved.level < 1 || saved.level > MAX_LEVEL)) return false;
  for (const key of ['exp', 'hp', 'mp', 'stones', 'age', 'ageUpdatedAt', 'overflowExp', 'unstableUntil', 'lastOverflowReturned', 'alchemyExp']) {
    if (has(key) && !nonnegative(saved[key])) return false;
  }
  for (const key of ['sectContribution', 'classVersion', 'questRewardVersion', 'moralVersion', 'classRefundSp', 'seclusionYearsToday', 'breakthroughFails', 'breakthroughBonusLevels', 'alchemyLevel', 'unspentStatPoints']) {
    if (has(key) && !count(saved[key])) return false;
  }
  for (const key of ['daoHeart', 'morality'] as const) {
    const value = saved[key], rule = MORAL_STATE[key];
    if (has(key) && (typeof value !== 'number' || !Number.isSafeInteger(value) || value < rule.min || value > rule.max)) return false;
  }
  if (has('allocatedStats') && !statRecord(saved.allocatedStats)) return false;
  if (has('encounters') && !dataRecord(saved.encounters)) return false;
  if (has('bonusStats') && (!dataRecord(saved.bonusStats) || ('insight' in saved.bonusStats && !count(saved.bonusStats.insight)))) return false;
  if (has('karmaFlags') && (!dataRecord(saved.karmaFlags) || !Object.entries(saved.karmaFlags).every(([key, value]) => safeKey(key) && typeof value === 'boolean'))) return false;
  if (has('affinity') && !isValidAffinity(saved.affinity)) return false;
  if (has('relationshipState') && !isValidRelationshipState(saved.relationshipState)) return false;
  if (has('companionRelations') && !isValidCompanionRelations(saved.companionRelations)) return false;
  if (has('tower') && !isValidTowerProgress(saved.tower)) return false;
  if (has('market') && !isValidMarketProgress(saved.market)) return false;
  if (has('forge') && !isValidForgeProgress(saved.forge)) return false;
  if (has('enhance') && !isValidEnhanceProgress(saved.enhance)) return false;
  if (has('enchant') && !isValidEnchantProgress(saved.enchant)) return false;
  if (has('salvage') && !isValidSalvageProgress(saved.salvage)) return false;
  for (const key of ['inventory', 'skills', 'skillGifted']) if (has(key) && !numbers(saved[key])) return false;
  for (const key of ['skillMastery', 'gatherRespawnAt']) if (has(key) && !numbers(saved[key], false)) return false;
  for (const key of ['job', 'selectedSect', 'name', 'rootElement', 'sectDailyContributionDay', 'dailyQuestResetDay', 'seclusionDay']) {
    if (has(key) && typeof saved[key] !== 'string') return false;
  }
  if (has('sectRank') && saved.sectRank !== null && typeof saved.sectRank !== 'string') return false;
  if (has('unstableRatio') && (typeof saved.unstableRatio !== 'number' || !Number.isFinite(saved.unstableRatio))) return false;
  if (has('equip') && (!dataRecord(saved.equip) || !Object.entries(saved.equip).every(([key, value]) => safeKey(key) && typeof value === 'string'))) return false;
  for (const key of ['classRewardClaims', 'completedTrials', 'learnedRecipes', 'tutorialsSeen', 'sectDailyContributionClaims', 'realmRewards', 'unstableStats']) {
    if (has(key) && !strings(saved[key])) return false;
  }
  if (has('hotbar') && (!Array.isArray(saved.hotbar) || !saved.hotbar.every(value => value === null || typeof value === 'string'))) return false;
  if (has('flags') && (!dataRecord(saved.flags) || !Object.entries(saved.flags).every(([key, value]) => flagKey(key) && typeof value === 'boolean'))) return false;
  if (has('position') && saved.position !== null) {
    const p = saved.position;
    if (!dataRecord(p) || typeof p.mapId !== 'string' || (p.mapId !== 'field_test' && !SECT_GATE_MAPS.has(p.mapId) && !Object.prototype.hasOwnProperty.call(TILED_MAPS, p.mapId))
      || typeof p.x !== 'number' || !Number.isFinite(p.x) || typeof p.y !== 'number' || !Number.isFinite(p.y)) return false;
  }
  if (has('pendingSectTrial') && saved.pendingSectTrial !== null) {
    const attempt = saved.pendingSectTrial;
    if (!dataRecord(attempt) || typeof attempt.id !== 'string' || !/^trial_sect_(taixu|lingfu|youying|wanshou)$/.test(attempt.id)) return false;
    const at = attempt.returnPosition;
    if (!dataRecord(at) || typeof at.mapId !== 'string' || (!SECT_GATE_MAPS.has(at.mapId) && !Object.prototype.hasOwnProperty.call(TILED_MAPS, at.mapId))
      || typeof at.x !== 'number' || !Number.isFinite(at.x) || typeof at.y !== 'number' || !Number.isFinite(at.y)) return false;
  }
  if (has('quests')) {
    if (!dataRecord(saved.quests)) return false;
    for (const [id, quest] of Object.entries(saved.quests)) {
      if (!safeKey(id) || !dataRecord(quest) || !['active', 'done'].includes(String(quest.state))) return false;
      for (const key of ['kills', 'crafted']) if (Object.prototype.hasOwnProperty.call(quest, key) && !numbers(quest[key])) return false;
      if (Object.prototype.hasOwnProperty.call(quest, 'reached') && typeof quest.reached !== 'boolean') return false;
      if (Object.prototype.hasOwnProperty.call(quest, 'talked') && (!dataRecord(quest.talked)
        || !Object.entries(quest.talked).every(([key, value]) => safeKey(key) && typeof value === 'boolean'))) return false;
    }
  }
  return true;
}

setSaveValidator(validSaveData);

