  position: SavePosition | null = null;
  /** 按配置路径覆盖布尔开关；未覆盖时沿用配表。 */
  flags: Record<string, boolean> = {};
  sectGrowthState: SectGrowthState = { donationBatches: {}, settledTransactions: {} };
  sectDailyContributionDay = '';
  sectDailyContributionClaims: string[] = [];
  /** 上次日常重置的本地日历日期（05:00 日界）；离线只补算到当前日。 */
  dailyQuestResetDay = '';
  dailyQuestCompletions: Record<string, string[]> = {};
  age = LIFESPAN.startAge;
  ageUpdatedAt = gameNow();
  seclusionDay = '';
  seclusionYearsToday = 0;
  seclusionHistory: { at: number; years: number; cost: number; gained: number; overflowed: number }[] = [];
  /** 瓶颈期装不下的修为，全额存进来，上限 overflowCap。旧档没有这个字段，读档时补 0 */
  overflowExp = 0;
  /** 突破失败次数（保底用，成功清零） */
  breakthroughFails = 0;
  /** 境界不稳到期时间（gameNow）与属性比例 */
  unstableUntil = 0;
  /** 已领过突破奖励（realms.json reward.hpMul/mpMul）的境界 id。按 id 去重，倍率每个境界只乘一次 */
  realmRewards: string[] = [];
  unstableRatio = 0;
  /** 境界不稳影响的属性，读 realms.json failPenalty.debuffStats */
  unstableStats: string[] = [];
  /** 刚突破时返还了多少，给界面飘字用，不参与公式 */
  lastOverflowReturned = 0;
  /** 返还的修为让新境界又升了几级 */
  breakthroughBonusLevels = 0;

  constructor() { this.hp = this.maxHp; this.mp = this.maxMp; }

  statKeys(): readonly StatKey[] { return STAT_KEYS; }
  allocatedStat(k: string) { return statKey(k) && Object.prototype.hasOwnProperty.call(this.allocatedStats, k) ? this.allocatedStats[k] : 0; }
  /** 四维总值 = 已确认加点 + 被动心法；升级不再自动分配。 */
  stat(k: string) { return this.allocatedStat(k) + this.passiveBonus(k) + (k === 'insight' && count(this.bonusStats?.insight) ? this.bonusStats.insight : 0); }

  /** delta 只接受四维的非负整数增量；缺键视为 0，不支持洗点。 */
  checkAllocate(delta: Record<string, number>): AllocateCheck {
    if (!statRecord(delta) || !statRecord(this.allocatedStats) || !count(this.unspentStatPoints)) return { ok: false, reason: 'invalid' };
    const entries = Object.entries(delta), total = entries.reduce((sum, [, n]) => sum + n, 0);
    if (!count(total) || entries.some(([key, n]) => !count(this.allocatedStat(key) + n))) return { ok: false, reason: 'invalid' };
    if (total > this.unspentStatPoints) return { ok: false, reason: 'overspend' };
    return { ok: true };
  }

  /** 确认时复检、一次扣点并保存；保存失败恢复原状态，草稿可重试。 */
  applyAllocate(delta: Record<string, number>): AllocateResult {
    const result = this.checkAllocate(delta);
    if (!result.ok) return result;
    const total = Object.values(delta).reduce((sum, n) => sum + n, 0);
    if (!total) return result;
    const previous = this.allocatedStats, previousUnspent = this.unspentStatPoints;
    this.allocatedStats = { ...previous };
    for (const [key, n] of Object.entries(delta)) this.allocatedStats[key] = this.allocatedStat(key) + n;
    this.unspentStatPoints -= total;
    try { if (this.save()) return result; } catch { /* 自定义存储也遵守原子回滚。 */ }
    this.allocatedStats = previous;
    this.unspentStatPoints = previousUnspent;
    return { ok: false, reason: 'save' };
  }
  private statBonus(attr: string) {
    let v = 0;
    for (const [k, eff] of Object.entries(GROWTH.statEffects as Record<string, Record<string, number>>)) v += (eff[attr] ?? 0) * this.stat(k);
    return v;
  }
  get realm() { return REALMS.find((r: any) => this.level >= r.levelMin && this.level <= r.levelMax) ?? REALMS[0]; }
  get realmName() {
    const r = this.realm;
    if (!r.stageLevels) return r.name;
    let i = 0; r.stageLevels.forEach((lv: number, k: number) => { if (this.level >= lv) i = k; });
    return `${r.name}·${r.stages[i]}`;
  }
  get skillsUnlocked() { return isCheatSkillsUnlocked() || this.realm.id !== 'mortal'; }

  exportSave(): Record<string, unknown> {
    const { transientItems, trialSkills, trialHotbarBefore, talisman, talismanUse, visitedMaps, talismanQuickSlots,
      talismanLevel, talismanExp, forgingLevel, forgingExp, senseState, senseRevealed, ...persistent } = this;
    const senseFields = featureEnabled('spiritScan') ? {
      ...(senseState !== undefined ? { senseState } : {}),
      ...(senseRevealed !== undefined && (!dataRecord(senseRevealed) || Object.keys(senseRevealed).length) ? { senseRevealed } : {}),
    } : {};
    const lifeSkillFields = featureEnabled('lifeSkillCurve') || talismanLevel !== (LIFE_SKILLS?.curve.initialLevel ?? 1)
      || talismanExp !== (LIFE_SKILLS?.curve.initialExp ?? 0) || forgingLevel !== (LIFE_SKILLS?.curve.initialLevel ?? 1)
      || forgingExp !== (LIFE_SKILLS?.curve.initialExp ?? 0) ? { talismanLevel, talismanExp, forgingLevel, forgingExp } : {};
    // 发版关口关闭且从未用过制符时，保持 v0.5.2 的存档形状；已存在的记录继续保存。
    const talismanFields = {
      ...(featureEnabled('talismanCraft') || JSON.stringify(talisman) !== JSON.stringify(emptyTalismanSave()) ? { talisman } : {}),
      ...(featureEnabled('talismanCraft') || JSON.stringify(talismanUse) !== JSON.stringify(emptyTalismanUseState()) ? { talismanUse } : {}),
      ...(featureEnabled('talismanCraft') || visitedMaps.length ? { visitedMaps } : {}),
      ...(featureEnabled('talismanCraft') || talismanQuickSlots.some(Boolean) ? { talismanQuickSlots } : {}),
    };
    const inventory: Record<string, number> = { ...this.inventory };
    for (const [id, count] of Object.entries(transientItems)) inventory[id] = Math.max(0, this.count(id) - count);
    const temporaryIds = Object.keys(trialSkills);
    return JSON.parse(JSON.stringify({ ...persistent, ...talismanFields, ...lifeSkillFields, ...senseFields, inventory, hotbar: trialHotbarBefore ?? this.hotbar,
      allocatedStats: normalizedStats(this.allocatedStats), unspentStatPoints: count(this.unspentStatPoints) ? this.unspentStatPoints : 0,
      buffs: this.buffs.filter(b => !temporaryIds.includes(b.id)),
      skillCooldowns: Object.fromEntries(Object.entries(this.skillCooldowns).filter(([id]) => !temporaryIds.includes(id))) }));
  }
  save(): boolean;
  save(options: { async: true }): Promise<boolean>;
  save(options?: { async: true }): boolean | Promise<boolean> {
    if (options?.async) return this.saveAsync();
    if (this.#saveMuted) return true;
    // IDB 无同步提交；旧玩法调用方须在异步事务 draft 内暂存，不能提前宣称成功。
    if (featureEnabled('indexedDbSaves')) return false;
    try { localStorage.setItem(SAVE_KEY, JSON.stringify(this.exportSave())); return true; } catch { return false; }
  }
  /** 沿用玩法忽略保存返回值的语义；开态提交到实例绑定的异步槽。 */
  persistSoon(): void {
    if (featureEnabled('indexedDbSaves')) void this.save({ async: true });
    else this.save();
  }
  /** 三槽提交以 IDB transaction.complete 为准；失败保留当前未确认的内存，允许重试。 */
  async saveAsync(): Promise<boolean> {
    if (!featureEnabled('indexedDbSaves')) return this.save();
    if (this.#saveMuted) return true;
    if (this.#transactionPending || this.#storageError) return false;
    let data: Record<string, unknown>;
    try { data = this.exportSave(); } catch { return false; }
    const slot = this.#slot ?? Progress.#activeSlot;
    return this.enqueueWrite(() => saveStore.writeSlot(slot, data));
  }
  private enqueueWrite<T>(write: () => Promise<T>): Promise<T> {
    const queued = this.#writeQueue.then(write, write);
    this.#writeQueue = queued.catch(() => undefined);
    return queued;
  }
  /** 面板删档、导入或换槽前等待当前实例的已排队提交。 */
  async flushSaves(): Promise<void> { await this.#writeQueue; }
  /**
   * 同步玩法可在隔离 draft 上暂存；只有 IDB 确认后才把整份内存交给当前角色。
   * apply 不跨 await，也不接收 Promise；失败不会抹掉原对象尚未确认的内存修改。
   */
  async runSaveTransactionAsync<T>(apply: (draft: Progress) => T | undefined): Promise<T | undefined> {
    if (!featureEnabled('indexedDbSaves')) return this.runSaveTransaction(() => apply(this));
    if (this.#transactionPending || this.#saveMuted || this.#storageError) return undefined;
    const slot = this.#slot ?? Progress.#activeSlot;
    this.#transactionPending = true;
    try {
      return await this.enqueueWrite(async () => {
        const before = structuredClone(Object.fromEntries(Object.entries(this).filter(([, value]) => typeof value !== 'function')));
        const draft = new Progress();
        Object.assign(draft, structuredClone(before));
        draft.#slot = slot;
        draft.#saveMuted = true;
        draft.#asyncDraft = true;
        const result = apply(draft);
        if (result instanceof Promise) { void result.catch(() => undefined); return undefined; }
        if (result === undefined) return undefined;
        const next = draft.exportSave();
        // 同步回调不得修改原实例，避免把别的进度一起覆盖到槽里。
        if (JSON.stringify(before) !== JSON.stringify(Object.fromEntries(Object.entries(this).filter(([, value]) => typeof value !== 'function')))) return undefined;
        if (!await saveStore.writeSlot(draft.#slot, next)) return undefined;
        // 首次成功提交即绑定本实例；切换全局 activeSlot 不能把既有实例写到另一档。
        this.#slot ??= slot;
        // 只发布 draft 改过的字段，保留等待 IDB 时原对象的其它内存变化。
        for (const key of new Set([...Object.keys(before), ...Object.keys(draft)])) {
          if (JSON.stringify(before[key]) === JSON.stringify(Reflect.get(draft, key))) continue;
          if (Object.prototype.hasOwnProperty.call(draft, key)) Reflect.set(this, key, structuredClone(Reflect.get(draft, key)));
          else Reflect.deleteProperty(this, key);
        }
        invalidateSenseSession(this);
        return result;
      });
    } catch { return undefined; }
    finally { this.#transactionPending = false; }
  }
  /** 一次真实保存提交整笔修改；拒绝、异常或写盘失败都恢复内存，允许重试。 */
  runSaveTransaction<T>(apply: () => T | undefined): T | undefined;
  runSaveTransaction<T>(apply: (draft: Progress) => T | undefined, options: { async: true }): Promise<T | undefined>;
  runSaveTransaction<T>(apply: (draft: Progress) => T | undefined, options?: { async: true }): T | undefined | Promise<T | undefined> {
    if (options?.async) return this.runSaveTransactionAsync(apply);
    if (this.#asyncDraft) {
      const previous = structuredClone(Object.fromEntries(Object.entries(this).filter(([, value]) => typeof value !== 'function')));
      try {
        const result = apply(this);
        if (result !== undefined && !(result instanceof Promise)) return result;
      } catch { /* draft 内嵌事务同样回滚，最终只由外层 IDB 提交。 */ }
      for (const key of Object.keys(this)) if (!Object.prototype.hasOwnProperty.call(previous, key)) Reflect.deleteProperty(this, key);
      Object.assign(this, previous);
      return undefined;
    }
    if (this.#saveMuted || featureEnabled('indexedDbSaves')) return undefined;
    // 不用 exportSave：回滚也要保留试炼临时物品/技能等当前内存数据。
    const previous = structuredClone(Object.fromEntries(Object.entries(this).filter(([, value]) => typeof value !== 'function')));
    const previousKeys = new Set(Object.keys(this));
    let saved = false;
    this.#saveMuted = true;
    try {
      const result = apply(this);
      if (result === undefined) return undefined;
      this.#saveMuted = false;
      saved = this.save();
      return saved ? result : undefined;
    } catch { return undefined; }
    finally {
      this.#saveMuted = false;
      if (!saved) {
        for (const key of Object.keys(this)) if (!previousKeys.has(key)) Reflect.deleteProperty(this, key);
        Object.assign(this, previous);
      }
    }
  }
  /** Runner 的数据快照；不暴露试炼临时物品，也不在读取时迁移或保存。 */
  encounterSave(): EncounterSave {
    return structuredClone({ exp: this.exp, stones: this.stones,
      inventory: Object.fromEntries(Object.keys(this.inventory).map(id => [id, this.permanentCount(id)])),
      daoHeart: this.daoHeart, morality: this.morality,
      ...(this.encounters !== undefined ? { encounters: this.encounters } : {}),
      ...(this.bonusStats !== undefined ? { bonusStats: this.bonusStats } : {}),
      ...(this.karmaFlags !== undefined ? { karmaFlags: this.karmaFlags } : {}) });
  }
  /** 扣药分桶、修为升级/溢出池与 runner 状态只写一次；写盘失败一起回滚。 */
  commitEncounterSave(next: EncounterSave): boolean {
    return this.runSaveTransaction(() => this.applyEncounterSave(next)) === true;
  }
  /** IDB 确认事务后才发布奇遇结果；失败保留原进度供 runner 重试。 */
  async commitEncounterSaveAsync(next: EncounterSave): Promise<boolean> {
    let snapshot: EncounterSave;
    try { snapshot = structuredClone(next); } catch { return false; }
    return await this.runSaveTransactionAsync(draft => draft.applyEncounterSave(snapshot)) === true;
  }
  private applyEncounterSave(next: EncounterSave): true | undefined {
    const baseExp = next.exp ?? this.exp, inventory = next.inventory ?? {};
    if (!count(baseExp) || baseExp < this.exp || !count(next.stones) || !dataRecord(inventory)
      || !Object.entries(inventory).every(([id, n]) => !!ITEMS[id] && count(n))
      || !dataRecord(next.encounters) || !count(next.daoHeart) || next.daoHeart > 100
      || !Number.isSafeInteger(next.morality) || next.morality! < -100 || next.morality! > 100
      || next.bonusStats !== undefined && (!dataRecord(next.bonusStats) || 'insight' in next.bonusStats && !count(next.bonusStats.insight))) return undefined;
    for (const id of new Set([...Object.keys(this.inventory), ...Object.keys(inventory)])) {
      const owned = this.permanentCount(id), wanted = inventory[id] ?? 0;
      if (!count(owned)) return undefined;
      if (wanted < owned) this.removeItem(id, owned - wanted);
      else if (wanted > owned) this.addItem(id, wanted - owned);
    }
    this.stones = next.stones!;
    this.daoHeart = next.daoHeart!; this.morality = next.morality!;
    this.encounters = structuredClone(next.encounters);
    this.bonusStats = next.bonusStats === undefined ? undefined : structuredClone(next.bonusStats);
    this.karmaFlags = next.karmaFlags === undefined ? undefined : structuredClone(next.karmaFlags);
    const gained = baseExp - this.exp;
    if (gained > 0) this.gainExp(gained, this.level, 'quest');
    return true;
  }
  /** 导入和读取存档共用迁移；只接收数据字段，不允许覆盖实例方法。 */
  importSave(saved: unknown): boolean;
  importSave(saved: unknown, options: { async: true }): Promise<boolean>;
  importSave(saved: unknown, options?: { async: true }): boolean | Promise<boolean> {
    if (options?.async) return this.importSaveAsync(saved);
    if (!saved || typeof saved !== 'object' || Array.isArray(saved)) return false;
    let restored: Progress;
    try {
      const fields: unknown = JSON.parse(JSON.stringify(saved));
      if (!validSaveData(fields)) return false;
      if (Progress.needsRelationshipMigration(fields) && !Progress.backupRelationshipSave(JSON.stringify(fields))) return false;
      restored = Progress.restore(fields, false);
    } catch { return false; }
    const previous = { ...this };
    Object.assign(this, restored);
    if (this.save()) { invalidateSenseSession(this); return true; }
    Object.assign(this, previous);
    return false;
  }
  async importSaveAsync(saved: unknown): Promise<boolean> {
    if (!featureEnabled('indexedDbSaves')) return this.importSave(saved);
    let fields: unknown;
    try { fields = JSON.parse(JSON.stringify(saved)); } catch { return false; }
    if (!validSaveData(fields)) return false;
    if (Progress.needsRelationshipMigration(fields) && !Progress.backupRelationshipSave(JSON.stringify(fields))) return false;
    let restored: Progress;
    try { restored = Progress.restore(fields, false); } catch { return false; }
    return await this.runSaveTransactionAsync(draft => {
      Object.assign(draft, restored);
      return true;
    }) === true;
  }
  private static restore(saved: unknown, persistMigrations: boolean, relationshipMigrationReady = true): Progress {
    syncTalismanMapAvailability();
    const p = new Progress();
    let saveRequested = false;
    Object.defineProperty(p, 'save', { configurable: true, value: () => { saveRequested = true; return true; } });
    let hadStoredRank = false, storedRank: string | null = null;
    let backfilled = false;
    try {
      if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
        const fields = saved as Record<string, unknown>;
        if (relationshipMigrationReady && Progress.needsRelationshipMigration(fields)) p.save();
        if (featureEnabled('lifeSkillCurve') && LIFE_SKILLS
          && ['talismanLevel', 'talismanExp', 'forgingLevel', 'forgingExp'].some(key => !Object.prototype.hasOwnProperty.call(fields, key))) p.save();
        if (!Object.prototype.hasOwnProperty.call(fields, 'questRewardVersion')) p.questRewardVersion = 0;
        if (!Object.prototype.hasOwnProperty.call(fields, 'moralVersion')) p.moralVersion = 0;
        hadStoredRank = Object.prototype.hasOwnProperty.call(fields, 'sectRank');
        if (hadStoredRank) storedRank = fields.sectRank as string | null;
        for (const key of Object.keys(p)) if (!['transientItems', 'trialSkills', 'trialHotbarBefore'].includes(key) && Object.prototype.hasOwnProperty.call(fields, key)) {
          Object.assign(p, { [key]: fields[key] });
        }
        if (!Object.prototype.hasOwnProperty.call(fields, 'allocatedStats')) {
          // 只将旧公式结算一次；保留既有四维/战力，不补发已花掉的等级点。
          const levels = count(p.level) && p.level >= 1 ? p.level - 1 : 0;
          p.allocatedStats = Object.fromEntries(STAT_KEYS.map(key => [key, AUTO_STATS[key] * levels]));
          p.unspentStatPoints = 0;
          p.save();
        } else if (!Object.prototype.hasOwnProperty.call(fields, 'unspentStatPoints')) p.save();
      }
      const statsBefore = JSON.stringify([p.allocatedStats, p.unspentStatPoints]);
      p.allocatedStats = normalizedStats(p.allocatedStats);
      p.unspentStatPoints = count(p.unspentStatPoints) ? p.unspentStatPoints : 0;
      if (statsBefore !== JSON.stringify([p.allocatedStats, p.unspentStatPoints])) p.save();
      p.overflowExp = Math.max(0, Math.floor(Number(p.overflowExp) || 0));
      if (Number.isFinite(p.overflowCap)) p.overflowExp = Math.min(p.overflowExp, p.overflowCap);
      if (relationshipMigrationReady && dataRecord(p.relationshipState) && p.relationshipState.version === 0) {
        p.relationshipState = { ...p.relationshipState, version: RELATIONSHIP_VERSION };
      }
      p.ensureDefaults();
      // 备份失败时留在未就绪版本；普通读档继续，关系消费者不得结算。
      if (!relationshipMigrationReady) p.relationshipState = { ...p.relationshipState, version: 0 };
      p.resetDailyQuests();
      p.advanceAge();
      const legacyFoxJoin = p.questRewardVersion < QUEST_REWARD_VERSION && p.quests.q_fox?.state === 'done'
        && !classDef(p.job) && !Object.keys(p.quests).some(id => classForQuest(id) && p.quests[id]?.state === 'done');
      // 先登记老玩家的宗门，避免按新突破表补通用技时抢动既有快捷栏。
      backfilled = [p.backfillRealmRewards(), p.backfillClass(false), p.backfillQuestSkills(), p.backfillQuestRecipes(), p.ensureSwordRideGranted()].some(Boolean);
      // 原职业/已交付拜入任务是正式入宗事实；试炼、帖和山门位置不参与迁移。
      p.sectRank = hadStoredRank && !(legacyFoxJoin && storedRank === null) ? storedRank : p.sect ? SECT_RANKS.rules.initialRank : null;
      p.hp = Math.min(p.hp || p.maxHp, p.maxHp);
      // 已提交神识可恰好耗尽灵力；仅新玩法有历史时保留 0，关闭时沿用旧档行为。
      p.mp = Math.min(featureEnabled('spiritScan') && p.senseState?.lastScanId && p.mp === 0 ? 0 : p.mp || p.maxMp, p.maxMp);
    } finally { Reflect.deleteProperty(p, 'save'); }
    if (persistMigrations && relationshipMigrationReady && (saveRequested || backfilled || !hadStoredRank)) p.save();
    return p;
  }
  private static needsRelationshipMigration(saved: Record<string, unknown>): boolean {
    const state = saved.relationshipState;
    return !Object.prototype.hasOwnProperty.call(saved, 'affinity') || !Object.prototype.hasOwnProperty.call(saved, 'relationshipState')
      || dataRecord(state) && (!Object.prototype.hasOwnProperty.call(state, 'version') || state.version === 0);
  }
  private static backupRelationshipSave(raw: string): boolean {
    try {
      if (localStorage.getItem(RELATIONSHIP_BACKUP_KEY) === null) localStorage.setItem(RELATIONSHIP_BACKUP_KEY, raw);
      return true;
    } catch { return false; }
  }
  static load(): Progress;
  static load(options: { async: true; slot?: SlotKey }): Promise<Progress>;
  static load(options?: { async: true; slot?: SlotKey }): Progress | Promise<Progress> {
    if (options?.async) return Progress.loadAsync(options.slot);
    if (featureEnabled('indexedDbSaves')) throw new Error('IndexedDB 存档须 await Progress.loadAsync()');
    let saved: unknown;
    let relationshipMigrationReady = true;
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (raw) {
        saved = JSON.parse(raw);
        if (dataRecord(saved) && Progress.needsRelationshipMigration(saved)) relationshipMigrationReady = Progress.backupRelationshipSave(raw);
      }
    } catch { /* 存档损坏就重开 */ }
    try { return Progress.restore(saved, true, relationshipMigrationReady); } catch { return Progress.restore(undefined, true); }
  }
  static reset(): boolean;
  static reset(options: { async: true; slot?: SlotKey }): Promise<boolean>;
  static reset(options?: { async: true; slot?: SlotKey }): boolean | Promise<boolean> {
    if (options?.async) return Progress.resetAsync(options.slot);
    if (featureEnabled('indexedDbSaves')) return false;
    try { localStorage.removeItem(SAVE_KEY); return true; } catch { return false; }
  }
  /** 不可读的槽返回带 storageError 的只读角色，禁止误当空槽覆盖。 */
  static async loadAsync(slot: SlotKey = Progress.#activeSlot): Promise<Progress> {
    if (!featureEnabled('indexedDbSaves')) return Progress.load();
    if (!SAVE_SLOT_KEYS.some(key => key === slot)) throw new TypeError('存档位只允许 1、2、3');
    let saved: Record<string, unknown> | undefined;
    let storageError: string | undefined;
    try {
      const migration = await saveStore.migrateLegacyLocalStorage();
      const record = await saveStore.readSlot(slot);
      saved = record?.data;
      if (migration === 'failed' && !record) throw new Error('旧存档迁移失败');
    } catch {
      // 错误不是空槽：可展示仍在 localStorage 的原角色，但必须禁止覆盖写入。
      storageError = '存档读取或迁移失败，原档已保留，请重试读档';
      if (slot === 1) try {
        const raw = localStorage.getItem(SAVE_KEY);
        const fields: unknown = raw ? JSON.parse(raw) : undefined;
        if (validSaveData(fields)) saved = fields;
      } catch { /* 旧档也不可读时只展示新角色，保持禁止写入。 */ }
    }
    let relationshipMigrationReady = true;
    if (saved && Progress.needsRelationshipMigration(saved)) {
      relationshipMigrationReady = Progress.backupRelationshipSave(JSON.stringify(saved));
    }
    const previousSkills = saved?.skills;
    const previouslyOwned = dataRecord(previousSkills) && typeof previousSkills.sword_ride === 'number' && previousSkills.sword_ride > 0;
    let p: Progress;
    try { p = Progress.restore(saved, false, relationshipMigrationReady); }
    catch {
      p = Progress.restore(undefined, false);
      storageError = '存档结构无法读取，原档已保留，请恢复备份后重试';
    }
    p.#slot = slot;
    p.#storageError = storageError;
    Progress.setActiveSlot(slot);
    // 御剑补缺与同步读档走同一规则；已拥有的档不重复写入、升级或播提示。
    if (saved && !previouslyOwned && (p.skills.sword_ride ?? 0) > 0 && !storageError && relationshipMigrationReady) {
      if (!await p.save({ async: true })) p.#storageError = '御剑技能补齐保存失败，原档已保留，请重试读档';
    }
    return p;
  }
  static async resetAsync(slot: SlotKey = Progress.#activeSlot): Promise<boolean> {
    return featureEnabled('indexedDbSaves') ? saveStore.deleteSlot(slot) : Progress.reset();
  }

  /** 持帖可在试炼成功前改选；不消耗拜帖，也不授予职业或奖励。 */
  selectSect(sectId: string): boolean {
    const cls = CLASS_LIST.find(c => c.sect === sectId);
    if (!cls || !classEntryEnabled(cls) || this.job || this.pendingSectTrial || this.count('five_sect_token') <= 0) return false;
    if (sectId !== this.selectedSect && this.completedTrials.some(id => /^trial_sect_(taixu|lingfu|youying|wanshou)$/.test(id))) return false;
    const previous = this.selectedSect;
    this.selectedSect = sectId;
    if (this.save()) return true;
    this.selectedSect = previous;
    return false;
  }

  setPosition(mapId: string, x: number, y: number): boolean;
  setPosition(mapId: string, x: number, y: number, options: { async: true }): Promise<boolean>;
  setPosition(mapId: string, x: number, y: number, options?: { async: true }): boolean | Promise<boolean> {
    if (options?.async) return this.setPositionAsync(mapId, x, y);
    if ((mapId !== 'field_test' && !Object.prototype.hasOwnProperty.call(TILED_MAPS, mapId)) || !Number.isFinite(x) || !Number.isFinite(y)) return false;
    this.position = { mapId, x, y };
    return this.save();
  }
  private async setPositionAsync(mapId: string, x: number, y: number): Promise<boolean> {
    if (!featureEnabled('indexedDbSaves')) return this.setPosition(mapId, x, y);
    if ((mapId !== 'field_test' && !Object.prototype.hasOwnProperty.call(TILED_MAPS, mapId)) || !Number.isFinite(x) || !Number.isFinite(y)) return false;
    this.position = { mapId, x, y };
    return this.save({ async: true });
  }
  setSectRank(rank: string | null): boolean {
    if (!this.sect || rank === null || !SECT_RANKS.ranks.some(entry => entry.id === rank)) return false;
    this.sectRank = rank;
    return this.save();
  }
  setConfigFlag(key: string, value: boolean): boolean {
    if (!flagKey(key) || typeof value !== 'boolean') return false;
    this.flags[key] = value;
    return this.save();
  }
  configFlag(key: string, fallback: boolean): boolean {
    return Object.prototype.hasOwnProperty.call(this.flags, key) ? this.flags[key] === true : fallback === true;
  }

  /** 教学首次触发就存档，换图与刷新后都不重复弹出。 */
  markTutorialSeen(id: string): boolean {
    if (!id || this.tutorialsSeen.includes(id)) return false;
    this.tutorialsSeen.push(id);
    this.persistSoon();
    return true;
  }

  gainSectContribution(amount: number) {
    if (!Number.isFinite(amount) || amount <= 0) return 0;
    const gained = Math.floor(amount);
    this.sectContribution += gained; this.persistSoon();
    return gained;
  }

  spendSectContribution(amount: number) {
    if (!Number.isFinite(amount) || amount < 0 || !Number.isInteger(amount) || this.sectContribution < amount) return false;
    this.sectContribution -= amount; this.persistSoon();
    return true;
  }

  /** 登录、接取、交付及在线检查共用；过期未交付任务也作废，不扣背包材料。 */
  resetDailyQuests(now = gameNow()) {
    // 关闭期间冻结日期、任务和收据；重新开放后再按原日界规则刷新。
    if (!featureEnabled('sectDaily')) return false;
    const day = dailyQuestDay(now);
    if (this.dailyQuestResetDay === day) return false;
    this.dailyQuestResetDay = day;
    for (const id of Object.keys(this.quests)) if (QUESTS[id]?.daily) delete this.quests[id];
    if (this.sectDailyContributionDay !== day) {
      this.sectDailyContributionDay = day;
      this.sectDailyContributionClaims = [];
    }
    this.dailyQuestCompletions = {};
    // 缺重置日期的旧档仍保留当天已领取收据，避免迁移时重新开放同一奖励。
    for (const id of this.sectDailyContributionClaims) {
      const q = QUESTS[id];
      if (q?.daily && q.sect) (this.dailyQuestCompletions[q.sect] ??= []).push(id);
    }
    this.persistSoon();
    return true;
  }

  canCompleteSectDailyQuest(sourceId: string, now = gameNow()) {
    if (!featureEnabled('sectDaily')) return false;
    this.resetDailyQuests(now);
    const q = QUESTS[sourceId];
    return !!q?.daily && dailyRewardsReady(q) && this.sect === q.sect
      && !this.sectDailyContributionClaims.includes(sourceId)
      && !(this.dailyQuestCompletions[q.sect!] ?? []).includes(sourceId)
      && (this.dailyQuestCompletions[q.sect!] ?? []).length < DAILY_QUEST_LIMIT;
  }

  /** 唯一领取判定：新交付与旧贡献回调共用任务 id、日界、每宗限额及存档收据。 */
  private claimSectDailyQuest(sourceId: string, now: number): number | undefined {
    if (!this.canCompleteSectDailyQuest(sourceId, now) || this.quests[sourceId]?.state !== 'done') return undefined;
    const q = QUESTS[sourceId], amount = dailyContribution(q)!;
    this.sectDailyContributionClaims.push(sourceId);
    (this.dailyQuestCompletions[q.sect!] ??= []).push(sourceId);
    return amount;
  }

  onSectDailyQuestCompleted(sourceId: string, now = gameNow()) {
    const amount = this.claimSectDailyQuest(sourceId, now);
    if (amount === undefined) return 0;
    const gained = this.gainSectContribution(amount);
    this.persistSoon(); // 显式 0 也必须落领取记录。
    return gained;
  }

  /** 由任务交付事务调用；完成状态、授职和全部奖励一起写盘后才通知场景。 */
  settleQuestRewards(q: QuestDef, force = false): QuestRewardSettlement | undefined {
    if (!this.#saveMuted || q.daily || this.quests[q.id]?.state !== 'done') return undefined;
    const rw = q.rewards, cls = classForQuest(q.id), job = cls?.id ?? rw.job;
    const forced = force && isCheatEnabled();
    const advanced = !!job && this.advanceClass(job);
    // 作弊强制交付可领取奖励，但不改换已有职业。
    if (job && !advanced && !forced) return undefined;
    const exp = rw.exp ? this.gainExp(rw.exp, this.level, 'quest')
      : { gained: 0, levels: 0, blocked: false, overflowed: 0, overflowFilled: false };
    if (rw.spiritStone) this.stones += rw.spiritStone;
    // 拜入道袍已由 advanceClass 发放并换装，不能重复进背包。
    const items = (rw.items ?? []).filter(it => !advanced || it.item !== cls?.robeId).map(it => {
      if (ITEMS[it.item]?.type === 'equip') return { ...it, equipped: this.gainEquip(it.item) };
      this.addItem(it.item, it.count);
      return { ...it };
    });
    this.grantQuestRecipes(q);
    for (const skill of rw.skills ?? []) this.grantSkill(skill.id, skill.level, forced);
    return { exp, items, skills: (rw.skills ?? []).filter(skill => !forced || (this.skills[skill.id] ?? 0) >= skill.level).map(skill => skill.id) };
  }

  /** 交付已验证目标并扣材料；整条日常的普通奖励与贡献在同一同步事务内保存。 */
  settleSectDailyQuest(sourceId: string, now = gameNow()): DailyQuestReward | undefined {
    const contribution = this.claimSectDailyQuest(sourceId, now);
    if (contribution === undefined) return undefined;
    const q = QUESTS[sourceId], rw = q.rewards;
    const exp = rw.exp ? this.gainExp(rw.exp, this.level, 'quest')
      : { gained: 0, levels: 0, blocked: false, overflowed: 0, overflowFilled: false };
    this.stones += rw.spiritStone;
    const items = (rw.items ?? []).map(it => {
      if (ITEMS[it.item]?.type === 'equip') return { ...it, equipped: this.gainEquip(it.item) };
      this.addItem(it.item, it.count);
      return { ...it };
    });
    this.grantQuestRecipes(q);
    for (const skill of rw.skills ?? []) this.grantSkill(skill.id, skill.level);
    // 贡献接口负责余额及最后的完整存档，0 时另存，不能再由旧回调追加奖励。
    this.gainSectContribution(contribution);
    this.persistSoon();
    return { exp, contribution, items, skills: (rw.skills ?? []).map(skill => skill.id) };
  }

  private equipSum(stat: string) {
    return Object.values(this.equip).reduce((s, id) => s + (ITEMS[id]?.stats?.[stat] ?? 0), 0);
  }
  /** 外观派生自当前装备，不额外存档；旧狐裘表没有 appearance，在代码中兼容。 */
  get appearance(): string | undefined {
    for (const id of Object.values(this.equip)) {
      const appearance = ITEMS[id]?.appearance ?? (id === 'fox_robe' ? 'fox_robe' : undefined);
      if (typeof appearance === 'string' && appearance.length > 0) return appearance;
    }
    return undefined;
  }
  get maxHp() { return Math.round((GROWTH.base.hp + GROWTH.perLevel.hp * (this.level - 1) + this.statBonus('hp') + this.equipSum('hp')) * this.realmMul('hpMul') * this.debuffMul('hp')); }
  get maxMp() { return Math.round((GROWTH.base.mp + GROWTH.perLevel.mp * (this.level - 1) + this.statBonus('mp')) * (1 + this.passiveBonus('mpMaxRatio')) * this.realmMul('mpMul') * this.debuffMul('mp')); }
  /** 突破奖励倍率：已领奖励的境界各乘一次（同一境界重复记录也只算一次） */
  realmMul(key: 'hpMul' | 'mpMul') {
    let m = 1;
    for (const id of new Set(this.realmRewards)) { const v = Number((REALMS.find((r: any) => r.id === id) as any)?.reward?.[key]); if (Number.isFinite(v) && v > 0) m *= v; }
    return m;
  }
  /** 旧存档补发：已经越过的境界（levelMax < 当前等级）都应领过奖励 */
  backfillRealmRewards() {
    if (!Array.isArray(this.realmRewards)) this.realmRewards = [];
    const before = this.realmRewards.length;
    const set = new Set(this.realmRewards);
    for (const r of REALMS as any[]) if (r.levelMax < this.level) set.add(r.id);
    this.realmRewards = [...set];
    return this.realmRewards.length !== before;
  }
  get atk() { return (GROWTH.base.atk + GROWTH.perLevel.atk * (this.level - 1) + this.statBonus('atk') + this.equipSum('atk') + this.passiveBonus('atk')) * this.debuffMul('atk'); }
  /** matk 基础成长尚未落表：登记表显式指定沿 atk 基础，心法神识仍按 statEffects.spirit.matk 换算。 */
  get matk() {
    const fallback = CLASS_RULES.damageBaseFallback;
    const fallbackStats = GROWTH.base.matk == null ? this.statBonus(fallback) : 0;
    const base = GROWTH.base.matk ?? GROWTH.base[fallback] ?? 0;
    const growth = GROWTH.perLevel.matk ?? GROWTH.perLevel[fallback] ?? 0;
    const equipment = Object.values(this.equip).reduce((sum, id) => {
      const stats = ITEMS[id]?.stats ?? {};
      return sum + (stats.matk ?? stats[fallback] ?? 0);
    }, 0);
    return (base + growth * (this.level - 1) + fallbackStats + this.statBonus('matk') + equipment + this.passiveBonus('matk')) * this.debuffMul('matk');
  }
  get def() { return (GROWTH.base.def + GROWTH.perLevel.def * (this.level - 1) + this.statBonus('def') + this.equipSum('def')) * this.debuffMul('def'); }
  /** 突破失败的「境界不稳」：到期前攻防 × (1 + debuffStatRatio)。暂只作用于攻击、防御（气血/灵力上限不动，免得回血逻辑乱） */
  get unstable() { return gameNow() < this.unstableUntil; }
  /** 境界不稳：只对 unstableStats 里列出的属性生效 */
  debuffMul(stat: string) { return Array.isArray(this.unstableStats) && this.unstableStats.includes(stat) ? this.unstableMul : 1; }
  get unstableMul() { return this.unstable ? 1 + this.unstableRatio : 1; }
  /** 突破成功率明细（03 文档 1.3 节 + breakthrough.json）。丹药品质暂按 low（物品还没有品质字段） */
  breakthroughRate(withClearMind = this.count('clear_mind_pill') > 0, quality = 'low') {
    const B = BREAKTHROUGH, r = this.realm;
    const base = Number(r.baseRate ?? 0);
    const pill = Number(B.pillQualityBonus?.[quality] ?? 0);
    const insight = Math.min(B.insightBonusCap ?? 0, this.stat('insight') * (B.insightBonusPerPoint ?? 0));
    const clear = withClearMind ? (B.clearMindPillBonus ?? 0) : 0;
    const pity = this.breakthroughFails * (B.pityPerFail ?? 0);
    const rate = Math.min(B.maxRate ?? 1, base + pill + insight + clear + pity);
    return { rate, base, pill, insight, clear, pity };
  }
  get expNeed() { return EXP_TO_NEXT[String(this.level)] ?? Infinity; }
  get atBreakthrough() { return BREAKTHROUGH_LEVELS.includes(this.level) && this.exp >= this.expNeed; }
  /**
   * 上限 = 卡住这一级、修为条正要填满的数 × overflowPoolRatio。
   * 9 级瓶颈取 exp_curve 的 9→10（382），不用 10→11（312）。
   */
  get overflowCap() {
    const bar = EXP_TO_NEXT[String(this.level)];
    if (bar == null || !Number.isFinite(bar)) return 0;
    return Math.max(0, Math.round(bar * (BREAKTHROUGH.overflowPoolRatio ?? 0.5)));
  }

  /** 葫芦三态：0 空、未满半、到上限满。池子被扣回去时跟着切 */
  get overflowTier(): 'empty' | 'half' | 'full' {
    if (this.overflowExp <= 0) return 'empty';
    if (this.overflowCap > 0 && this.overflowExp >= this.overflowCap) return 'full';
    return 'half';
  }

  /** 玩家打怪伤害：max(1, round(atk·ratio·rand(0.9,1.1) − def))，怪高 n 级 ×max(0.6, 1−0.05n) */
  damageTo(monLevel: number, monDef: number, ratio = 1, damageStat: 'atk' | 'matk' = 'atk', crit = false, critMultiplier = 1.5) {
    const n = monLevel - this.level;
    const gap = n > 0 ? Math.max(0.6, 1 - 0.05 * n) : 1;
    const minRoll = Math.min(1.1, 0.9 + Math.max(0, this.passiveBonus('minDamageRatio')));
    const roll = minRoll + Math.random() * (1.1 - minRoll);
    const attack = damageStat === 'matk' ? this.matk : this.atk;
    return Math.max(1, Math.round((attack * ratio * roll * (crit ? critMultiplier : 1) - monDef) * gap));
  }
  /** 符箓绝对基础伤害，只复用等级差和扣防，不乘角色攻击/职业技能增幅。 */
  fixedDamageTo(baseDamage: number, monLevel: number, monDef: number) {
    const n = monLevel - this.level;
    const gap = n > 0 ? Math.max(0.6, 1 - 0.05 * n) : 1;
    return Math.max(1, Math.round((baseDamage * (0.9 + Math.random() * 0.2) - monDef) * gap));
  }
  /** 单次技能伤害：元素和暴击先乘攻击，之后每段分别扣防。剑修旧公式保持原样。 */
  skillDamageTo(id: string, level: number, monLevel: number, monDef: number, ratio: number, forceCrit = false) {
    const def = SKILLS[id];
    if (!def) return this.damageTo(monLevel, monDef, ratio);
    const stat = def.effects.damageStat === 'matk' ? 'matk' : 'atk';
    const sameElement = !!this.rootElement && def.effects.element === this.rootElement;
    const elementBonus = sameElement ? this.effectBonus('sameElementDamageBonus') : 0;
    const critMultiplier = skillNumber(def, 'critDamage', level) || 1.5;
    return this.damageTo(monLevel, monDef, ratio * (1 + elementBonus + this.buffBonus('damageBonus')), stat, forceCrit, critMultiplier);
  }
  /** 怪打玩家：同一公式 */
  damageFrom(monAtk: number, ratio = 1, otherReductions: number[] = []) {
    const raw = Math.max(1, monAtk * ratio * (0.9 + Math.random() * 0.2) - this.def);
    const multiplier = featureEnabled('talismanCraft') ? talismanDamageMultiplier(this.talismanUse, gameNow(), otherReductions) : 1;
    return Math.max(1, Math.round(raw * multiplier));
  }

  /** 加修为，返回升了几级。怪比玩家低 5 级以上按 max(0.2, 1−0.1(n−4)) 衰减；突破关口停住 */
  gainExp(base: number, monLevel: number, source: 'kill' | 'quest' = 'kill'): { gained: number; levels: number; blocked: boolean; overflowed: number; overflowFilled: boolean } {
    const n = this.level - monLevel;
    const talismanBonus = featureEnabled('talismanCraft') ? talismanGatherBonus(this.talismanUse, gameNow(), source) : 0;
    const raw = Math.max(1, Math.round(base * (n >= 5 ? Math.max(0.2, 1 - 0.1 * (n - 4)) : 1) * (1 + this.statBonus('expBonus') + talismanBonus)));
    return this.settleExp(raw);
  }

  /** 闭关公式已经包含境界/灵气/房间倍率，不再套击杀衰减或悟性倍率。 */
  gainCultivation(base: number) { return this.settleExp(Math.max(0, Math.round(base))); }

  private settleExp(raw: number) {
    const before = this.totalExpMark();
    const poolBefore = this.overflowExp;
    const capBefore = this.overflowCap;
    const wasFull = capBefore > 0 && poolBefore >= capBefore;
    this.exp += raw;
    let levels = 0, blocked = false;
    while (this.level < MAX_LEVEL && this.exp >= this.expNeed) {
      if (BREAKTHROUGH_LEVELS.includes(this.level)) {
        const leftover = this.exp - this.expNeed;
        this.exp = this.expNeed; blocked = true;
        if (leftover > 0) this.storeOverflow(leftover);
        break;
      }
      this.exp -= this.expNeed; this.level++; levels++;
      this.unspentStatPoints += Number(GROWTH.perLevel.statPoints) || 0;
    }
    if (levels) { this.hp = this.maxHp; this.mp = this.maxMp; }   // G2：升级回满（瓶颈级本身不升级，不会走到这里）
    // G3：瓶颈期没进修为条的部分不算“获得”；溢出池另计
    const gained = blocked ? Math.max(0, this.totalExpMark() - before) : raw;
    const overflowed = this.overflowExp - poolBefore;
    const overflowFilled = !wasFull && this.overflowCap > 0 && this.overflowExp >= this.overflowCap;
    return { gained, levels, blocked, overflowed, overflowFilled };
  }

  /** G12：修为条满了之后的结余全额存入，到上限（卡住那级 × overflowPoolRatio）截断 */
  private storeOverflow(leftover: number) {
    const want = Math.max(0, Math.round(leftover));
    const space = Math.max(0, this.overflowCap - this.overflowExp);
    this.overflowExp += Math.min(want, space);
  }

  /** 当前等级之前累计的修为 + 本级修为，用来算实际加了多少 */
  private totalExpMark() { let t = this.exp; for (let lv = 1; lv < this.level; lv++) t += EXP_TO_NEXT[String(lv)] ?? 0; return t; }

  /**
   * 突破失败扣修为。失败演出还没接进来，先把扣法定死：
   * 扣减量 = round(当前修为条 × ratio)，先扣溢出池，不够的部分再扣修为条。
   * ratio 由调用方传入（realms.json 的 failPenalty.expLossRatio）。
   */
  applyBreakthroughFail(ratio: number): { lost: number; fromPool: number; fromBar: number } {
    const r = Number.isFinite(ratio) ? Math.max(0, ratio) : 0;
    const loss = Math.max(0, Math.round(this.exp * r));
    const fromPool = Math.min(this.overflowExp, loss);
    const fromBar = Math.min(this.exp, loss - fromPool);
    this.overflowExp -= fromPool;
    this.exp -= fromBar;
    return { lost: fromPool + fromBar, fromPool, fromBar };
  }

  /** 突破：瓶颈级修为满 → 进入下一级，溢出池全部返还进新境界的修为（上限是瓶颈级修为条的一半） */
  breakthrough() {
    if (!this.atBreakthrough) return false;
    const pool = this.overflowExp;
    const left = this.realm.id;
    if (!this.realmRewards.includes(left)) this.realmRewards.push(left);
    this.overflowExp = 0;
    this.lastOverflowReturned = pool;
    this.exp = 0; this.level++;
    this.unspentStatPoints += Number(GROWTH.perLevel.statPoints) || 0;
    this.exp = pool;
    let bonus = 0;
    while (this.level < MAX_LEVEL && this.exp >= this.expNeed) {
      if (BREAKTHROUGH_LEVELS.includes(this.level)) { this.exp = this.expNeed; break; }
      this.exp -= this.expNeed; this.level++; bonus++;
      this.unspentStatPoints += Number(GROWTH.perLevel.statPoints) || 0;
    }
    this.breakthroughBonusLevels = bonus;
    // reward.unlock 是离开旧境界的奖励；只把已登记的技能接入赠技链。
    for (const id of REALMS.find((r: { id: string }) => r.id === left)?.reward?.unlock ?? []) {
      if (!SKILLS[id]) continue;
      if (id === 'sword_ride') this.ensureSwordRideGranted();
      else this.grantSkill(id, 1);
    }
    this.hp = this.maxHp; this.mp = this.maxMp;
    return true;
  }

  count(id: string) { return this.inventory[id] ?? 0; }
  /** 临时试炼物不属于可上交的永久库存；坏数量暂停本次消耗。 */
  permanentCount(id: string) {
    const owned = this.count(id), transient = this.transientItems[id] ?? 0;
    return Number.isSafeInteger(owned) && owned >= 0 && Number.isSafeInteger(transient) && transient >= 0 && transient <= owned
      ? owned - transient : NaN;
  }
  removeItem(id: string, n: number) {
    if (!Number.isFinite(n) || n <= 0) return;
    let left = Math.min(this.count(id), Math.floor(n));
    if (this.pillQualities[id]) {
      const qualities = this.pillQualityCounts(id);
      for (const quality of ['low', 'mid', 'high', 'supreme'] as PillQuality[]) {
        const used = Math.min(left, qualities[quality]); qualities[quality] -= used; left -= used;
      }
      this.pillQualities[id] = qualities;
    }
    this.inventory[id] = Math.max(0, this.count(id) - Math.floor(n));
  }

  pillQualityCounts(id: string): Record<PillQuality, number> {
    const counts: Record<PillQuality, number> = { low: 0, mid: 0, high: 0, supreme: 0 };
    let remaining = Math.max(0, this.count(id));
    for (const quality of ['low', 'mid', 'high', 'supreme'] as PillQuality[]) {
      const raw = Number(this.pillQualities[id]?.[quality]);
      const n = Number.isFinite(raw) ? Math.min(remaining, Math.max(0, Math.floor(raw))) : 0;
      counts[quality] = n; remaining -= n;
    }
    counts.low += remaining;
    return counts;
  }
  /** 与 removeItem 消耗顺序一致；老丹药及材料没有分桶时按下品。 */
  pillQuality(id: string): PillQuality {
    const counts = this.pillQualityCounts(id);
    return (['low', 'mid', 'high', 'supreme'] as PillQuality[]).find(quality => counts[quality] > 0) ?? 'low';
  }
  addCraftedPill(id: string, n: number, quality: PillQuality) {
    if (!Number.isFinite(n) || n <= 0) return;
    const counts = this.pillQualityCounts(id);
    this.addItem(id, Math.floor(n)); counts[quality] += Math.floor(n);
    this.pillQualities[id] = counts;
  }

  /** 与旧丹药共用同一品质账本，普通物品保持 itemId → count。 */
  qualityEnabled(id: string) { return ITEMS[id]?.qualityEnabled === true; }
  qualityCounts(id: string) { return this.pillQualityCounts(id); }
  countQuality(id: string, quality: PillQuality): number { return this.qualityCounts(id)[quality] ?? 0; }
  removeQuality(id: string, n: number, quality: PillQuality): boolean {
    if (!Number.isSafeInteger(n) || n <= 0 || !['low', 'mid', 'high', 'supreme'].includes(quality) || this.countQuality(id, quality) < n) return false;
    const qualities = this.qualityCounts(id);
    qualities[quality] -= n;
    this.pillQualities[id] = qualities;
    this.inventory[id] = this.count(id) - n;
    return true;
  }
  /** 当前无格数上限，只拒绝非法物品、数量及计数溢出。 */
  canAddCraftedItem(id: string, n: number): boolean {
    return Object.prototype.hasOwnProperty.call(ITEMS, id) && Number.isSafeInteger(n) && n > 0
      && Number.isSafeInteger(this.count(id)) && this.count(id) >= 0 && Number.isSafeInteger(this.count(id) + n);
  }
  addCraftedItem(id: string, n: number, quality?: PillQuality): boolean {
    if (!this.canAddCraftedItem(id, n)) return false;
    if (this.qualityEnabled(id)) {
      if (!quality || !['low', 'mid', 'high', 'supreme'].includes(quality)) return false;
      this.addCraftedPill(id, n, quality);
    } else this.addItem(id, n);
    return true;
  }
  /**
   * 仅在正式 ForgeGate 的同一保存事务内调用：完整成品先入库、forge 结果及收据先成立。
   * 不保存独立半笔登记，不按物品数量或装备槽制造身份，也不升级历史夹具记录。
   */
  registerFormalEnhanceInstance(result: ForgeCraftResult): boolean {
    try {
      const forge = this.forge;
      if (!isValidForgeProgress(forge)) return false;
      const committed = forge.crafts.find(row => row.craftResultRef === result.craftResultRef);
      if (!committed || JSON.stringify(committed) !== JSON.stringify(result)
        || !forge.receipts.includes(committed.craftResultRef) || committed.resultItem.count !== 1) return false;
      // API 本身也核实正式配方；拥有一个测试打造账本不能绕过默认 ForgeGate 的来源边界。
      const recipes = Object.values(RECIPES).filter(row => row.type === 'forge'
        && Reflect.get(row, 'blueprint') === committed.blueprintId);
      if (recipes.length !== 1) return false;
      const recipe = recipes[0];
      if (committed.blueprintCount !== 1 || recipe.output !== committed.resultItem.itemId
        || recipe.outputCount !== committed.resultItem.count || !Array.isArray(recipe.materials)
        || recipe.materials.length !== committed.materials.length
        || !recipe.materials.every(material => Number.isSafeInteger(material.count) && material.count > 0
          && committed.materials.some(other => other.itemId === material.item && other.count === material.count))) return false;
      const { instanceRef, itemId } = committed.resultItem;
      const item = Object.prototype.hasOwnProperty.call(ITEMS, itemId) ? ITEMS[itemId] : undefined;
      if (!isEnhanceInstanceRef(instanceRef) || !item || item.type !== 'equip' || !inPhase(item)
        || item.enabled === false || item.placeholder === true || item.qualityEnabled === true
        || !['weapon', 'robe', 'shoes'].includes(item.slot ?? '')
        || Object.prototype.hasOwnProperty.call(this.pillQualities, itemId)
        || this.count(itemId) !== this.permanentCount(itemId)) return false;
      const type = item.slot === 'weapon' ? 'weapon' : 'armor';
      const current = this.enhance;
      if (current !== undefined && !isValidEnhanceProgress(current)) return false;
      if (current?.formalSources?.some(source => this.formalEnhanceInstanceStatus(source.instanceRef) !== 'registered')) return false;
      const existing = current?.instances.find(row => row.instanceRef === instanceRef);
      // 重复登记只读保留当前等级；没有正式来源的历史同名记录绝不升格。
      if (existing) return existing.itemId === itemId && existing.type === type
        && this.formalEnhanceInstanceStatus(instanceRef) === 'registered';
      const sources = current?.formalSources ?? [];
      const registeredCount = sources.filter(source => current?.instances.some(row =>
        row.instanceRef === source.instanceRef && row.itemId === itemId)).length;
      const equippedCount = Object.entries(this.equip).filter(([slot, id]) =>
        id === itemId && slot === item.slot).length;
      const owned = this.permanentCount(itemId) + equippedCount;
      if (!Number.isSafeInteger(owned) || owned < registeredCount + 1) return false;
      const ledgerId = current?.ledgerId ?? `enhance_${crypto.randomUUID()}`;
      if (!isEnhanceId(ledgerId)) return false;
      const source: FormalEnhanceSource = {
        instanceRef, source: 'forge', forgeLedgerId: forge.ledgerId, craftResultRef: committed.craftResultRef,
        ownerSlot: this.#slot ?? Progress.#activeSlot,
      };
      const bag: EnhanceProgress = current ? structuredClone(current)
        : { version: 1, ledgerId, instances: [], enhancements: [], receipts: [] };
      bag.instances.push({ instanceRef, itemId, type, enhanceLevel: 0 });
      bag.formalSources = [...sources, source];
      if (!isValidEnhanceProgress(bag)) return false;
      this.enhance = bag;
      return true;
    } catch { return false; }
  }
  /** 只检查来源证明与本档完整打造绑定；装备 type、配置资格和当前持有关系交给 Gate。 */
  formalEnhanceInstanceStatus(instanceRef: string): 'registered' | 'foreign' | 'missing' {
    try {
      const sources = this.enhance?.formalSources;
      const source = Array.isArray(sources) ? sources.find(row => row.instanceRef === instanceRef) : undefined;
      if (!source) return 'missing';
      const forge = this.forge;
      if (source.source !== 'forge' || source.ownerSlot !== (this.#slot ?? Progress.#activeSlot)
        || !isValidForgeProgress(forge) || source.forgeLedgerId !== forge.ledgerId) return 'foreign';
      const craft = forge.crafts.find(row => row.craftResultRef === source.craftResultRef);
      const instance = this.enhance?.instances.find(row => row.instanceRef === instanceRef);
      return craft && forge.receipts.includes(craft.craftResultRef) && craft.resultItem.count === 1
        && source.instanceRef === `${craft.craftResultRef}:item` && craft.resultItem.instanceRef === source.instanceRef
        && instance?.itemId === craft.resultItem.itemId ? 'registered' : 'foreign';
    } catch { return 'foreign'; }
  }
  /** 生产新提交只取这组已登记来源；历史纯 instances 与夹具授权均不进入此组。 */
  formalEnhanceInstances(): EnhanceFixtureInstance[] {
    try {
      return this.enhance?.instances.filter(row => this.formalEnhanceInstanceStatus(row.instanceRef) === 'registered') ?? [];
    } catch { return []; }
  }
  bindTalismanSlot(index: number, item: string | null, quality?: PillQuality): boolean {
    if (!featureEnabled('talismanCraft') || !Number.isSafeInteger(index) || index < 0 || index >= HOTBAR_SLOTS.length) return false;
    if (item !== null && (!['talisman_fire', 'talisman_guard', 'talisman_return', 'talisman_gather'].includes(item)
      || !this.qualityEnabled(item) || !quality || !['low', 'mid', 'high', 'supreme'].includes(quality))) return false;
    return this.runSaveTransaction(() => { this.talismanQuickSlots[index] = item === null ? null : { item, quality: quality! }; return true; }) === true;
  }
  markMapVisited(id: string): boolean {
    if (!featureEnabled('talismanCraft') || !Object.prototype.hasOwnProperty.call(TILED_MAPS, id) || this.visitedMaps.includes(id)) return false;
    return this.runSaveTransaction(() => { this.visitedMaps.push(id); return true; }) === true;
  }

  grantRecipe(id: string) {
    if (!RECIPES[id] || this.learnedRecipes.includes(id)) return false;
    if (!this.recipeSkillPermission(id).ok) return false;
    this.learnedRecipes.push(id); return true;
  }
  /** 仅生活技能许可；角色、境界、任务条件仍由原入口检查。 */
  recipeSkillPermission(id: string): Readonly<{ ok: boolean; reason?: 'config' | 'skill_level'; rank?: number; minSkillLevel?: number }> {
    if (!featureEnabled('lifeSkillCurve')) return Object.freeze({ ok: true });
    const recipe = RECIPES[id];
    const skill = recipe?.type === 'talisman' || recipe?.type === 'grinding' ? 'talisman' : 'alchemy';
    const entry = LIFE_SKILLS && recipe ? lifeSkillRecipe(LIFE_SKILLS, skill, recipe) : null;
    if (!entry) return Object.freeze({ ok: false, reason: 'config' });
    const level = skill === 'alchemy' ? this.alchemyLevel : this.talismanLevel;
    if (!Number.isSafeInteger(level) || level < 1 || level > LIFE_SKILLS!.curve.maxLevel) return Object.freeze({ ok: false, reason: 'config' });
    return Object.freeze({ ...entry, ok: level >= entry.minSkillLevel,
      ...(level < entry.minSkillLevel ? { reason: 'skill_level' as const } : {}) });
  }
  grantQuestRecipes(q: QuestDef) {
    if (q.id === 'q_talisman_intro' && !featureEnabled('talismanCraft')) return [];
    const granted: string[] = [];
    for (const id of q.rewards.recipes ?? []) if (this.grantRecipe(id)) granted.push(id);
    return granted;
  }
  /** 公式字段当前是说明文本；只解析明确的乘数，不执行表内表达式。 */
  get alchemyExpNeed() {
    if (featureEnabled('lifeSkillCurve')) {
      return LIFE_SKILLS && this.alchemyLevel < LIFE_SKILLS.curve.maxLevel
        ? lifeSkillLevel(LIFE_SKILLS, 'alchemy', this.alchemyLevel).expToNext : Infinity;
    }
    const multiplier = Number(ALCHEMY_RULES.alchemyExp.toNext.match(/(\d+(?:\.\d+)?)\s*×/)?.[1] ?? 50);
    return this.alchemyLevel >= ALCHEMY_RULES.alchemyExp.maxLevel ? Infinity : multiplier * this.alchemyLevel;
  }
  gainAlchemyExp(amount: number) {
    if (featureEnabled('lifeSkillCurve')) return this.gainLifeSkillExp('alchemy', amount);
    if (!Number.isFinite(amount) || amount <= 0 || this.alchemyLevel >= ALCHEMY_RULES.alchemyExp.maxLevel) return 0;
    this.alchemyExp += Math.floor(amount);
    let levels = 0;
    while (this.alchemyLevel < ALCHEMY_RULES.alchemyExp.maxLevel && this.alchemyExp >= this.alchemyExpNeed) {
      this.alchemyExp -= this.alchemyExpNeed; this.alchemyLevel++; levels++;
    }
    if (this.alchemyLevel >= ALCHEMY_RULES.alchemyExp.maxLevel) this.alchemyExp = 0;
    return levels;
  }
  get talismanExpNeed() {
    return featureEnabled('lifeSkillCurve') && LIFE_SKILLS && this.talismanLevel < LIFE_SKILLS.curve.maxLevel
      ? lifeSkillLevel(LIFE_SKILLS, 'talisman', this.talismanLevel).expToNext : Infinity;
  }
  gainTalismanExp(amount: number) { return this.gainLifeSkillExp('talisman', amount); }
  private gainLifeSkillExp(id: 'alchemy' | 'talisman', amount: number) {
    if (!featureEnabled('lifeSkillCurve') || !LIFE_SKILLS || !Number.isFinite(amount) || amount <= 0) return 0;
    const levelKey = id === 'alchemy' ? 'alchemyLevel' : 'talismanLevel';
    const expKey = id === 'alchemy' ? 'alchemyExp' : 'talismanExp';
    const next = advanceLifeSkillProgress(LIFE_SKILLS, id, this[levelKey], this[expKey], amount);
    this[levelKey] = next.level; this[expKey] = next.exp;
    return next.levels;
  }
  lifeSkillView(id: LifeSkillId) {
    const level = id === 'alchemy' ? this.alchemyLevel : id === 'talisman' ? this.talismanLevel : this.forgingLevel;
    const exp = id === 'alchemy' ? this.alchemyExp : id === 'talisman' ? this.talismanExp : this.forgingExp;
    const enabled = featureEnabled('lifeSkillCurve');
    if (LIFE_SKILLS) return Object.freeze({ id, enabled, available: id !== 'forging',
      ...lifeSkillProgressView(LIFE_SKILLS, id, level, exp), configErrors: LIFE_SKILL_ERRORS });
    return Object.freeze({ id, enabled, available: false, level, exp,
      expToNext: id === 'alchemy' && !enabled && Number.isFinite(this.alchemyExpNeed) ? this.alchemyExpNeed : null,
      maxLevel: id === 'alchemy' && !enabled ? ALCHEMY_RULES.alchemyExp.maxLevel : null,
      maxed: id === 'alchemy' && !enabled && this.alchemyLevel >= ALCHEMY_RULES.alchemyExp.maxLevel,
      configErrors: LIFE_SKILL_ERRORS });
  }
  /** 获得装备：对应栏位空着或新装备更强就自动换上（装备界面做好前的过渡） */
  gainEquip(id: string) {
    const it = ITEMS[id] as any; if (!it?.slot) return false;
    if (it.sect && it.sect !== this.sect) { this.addItem(id, 1); return false; }
    if ((it.reqLevel ?? 1) > this.level) { this.addItem(id, 1); return false; }
    const cur = this.equip[it.slot];
    const score = (x?: string) => x ? Object.values(ITEMS[x]?.stats ?? {}).reduce((a, b) => a + b, 0) : -1;
    if (score(id) > score(cur)) { if (cur) this.addItem(cur, 1); this.equip[it.slot] = id; return true; }
    this.addItem(id, 1); return false;
  }

  /** UI-7 手动穿戴：只搬运永久背包库存，宗门/等级限制与 gainEquip 一致，不比较强弱。 */
  equipItem(id: string): EquipResult {
    const it = Object.prototype.hasOwnProperty.call(ITEMS, id) ? ITEMS[id] : undefined;
    if (!it || it.type !== 'equip' || !EQUIP_SLOTS.some(slot => slot === it.slot)) return { ok: false, reason: 'invalid' };
    if (!(this.permanentCount(id) > 0)) return { ok: false, reason: 'missing' };
    if (it.sect && it.sect !== this.sect) return { ok: false, reason: 'sect' };
    if ((it.reqLevel ?? 1) > this.level) return { ok: false, reason: 'level' };
    const slot = it.slot as EquipSlot, old = this.equip[slot];
    if (old && old !== id && !this.canReceiveItem(old)) return { ok: false, reason: 'overflow' };
    return this.changeEquip(() => {
      this.inventory[id] = this.count(id) - 1;
      if (old) this.addItem(old, 1);
      this.equip[slot] = id;
    });
  }

  /** 卸下不重新检查穿戴条件；旧档装备仍能安全回到背包。 */
  unequipSlot(slot: string): EquipResult {
    if (!EQUIP_SLOTS.some(key => key === slot)) return { ok: false, reason: 'invalid' };
    const old = this.equip[slot];
    if (!old) return { ok: false, reason: 'empty' };
    if (!this.canReceiveItem(old)) return { ok: false, reason: 'overflow' };
    return this.changeEquip(() => { this.addItem(old, 1); delete this.equip[slot]; });
  }

  private changeEquip(change: () => void): EquipResult {
    const inventory = this.inventory, equip = this.equip, hp = this.hp, mp = this.mp;
    this.inventory = { ...inventory }; this.equip = { ...equip };
    change();
    this.hp = Math.min(this.hp, this.maxHp); this.mp = Math.min(this.mp, this.maxMp);
    try { if (this.save()) return { ok: true }; } catch { /* 与 applyAllocate 相同：保存异常原子回滚。 */ }
    this.inventory = inventory; this.equip = equip; this.hp = hp; this.mp = mp;
    return { ok: false, reason: 'save' };
  }

  addItem(id: string, n: number) { this.inventory[id] = (this.inventory[id] ?? 0) + n; }
  /** 当前背包没有槽位上限；调用方先查物品表，此处拒绝非法和溢出数量。 */
  canReceiveItem(id: string, n = 1) {
    const count = this.count(id);
    return !!id && Number.isSafeInteger(n) && n > 0 && Number.isSafeInteger(count) && count >= 0
      && Number.isSafeInteger(count + n);
  }
  addTrialItem(id: string, n: number) {
    this.addItem(id, n);
    this.transientItems[id] = (this.transientItems[id] ?? 0) + n;
  }
  removeTrialItem(id: string, n: number) {
    const count = Math.min(n, this.transientItems[id] ?? 0);
    this.removeItem(id, count);
    this.transientItems[id] = Math.max(0, (this.transientItems[id] ?? 0) - count);
  }

  /** 旧档缺字段时补上，避免 Object.assign 把后面新增的数组弄丢或弄短。 */
  ensureDefaults() {
    syncTalismanMapAvailability();
    this.affinity = normalizeAffinity(this.affinity);
    // 缺失容器可迁移；显式坏收据原样保留，由消费者 fail-closed，不能清空重发。
    const relationship = normalizeRelationshipState(this.relationshipState);
    if (relationship) this.relationshipState = relationship;
    this.allocatedStats = normalizedStats(this.allocatedStats);
    this.unspentStatPoints = count(this.unspentStatPoints) ? this.unspentStatPoints : 0;
    if (typeof this.selectedSect !== 'string' || !CLASS_LIST.some(c => c.sect === this.selectedSect)) this.selectedSect = '';
    // 未注册山门的旧档落点安全回落霞；已由五宗或制符开关注册的山门保留原坐标。
    const unavailableGate = (mapId?: string) => typeof mapId === 'string' && SECT_GATE_MAPS.has(mapId)
      && !Object.prototype.hasOwnProperty.call(TILED_MAPS, mapId);
    if (unavailableGate(this.position?.mapId) || unavailableGate(this.pendingSectTrial?.returnPosition?.mapId)) {
      const town = TILED_MAPS.luoxia_town;
      const spawn = (town?.layers ?? []).flatMap((layer: any) => layer.objects ?? [])
        .find((object: any) => object.type === 'playerStart' || object.name === 'playerStart');
      if (spawn && Number.isFinite(spawn.x) && Number.isFinite(spawn.y)) {
        const at = { mapId: 'luoxia_town', x: spawn.x, y: spawn.y };
        if (unavailableGate(this.position?.mapId)) { this.position = { ...at }; this.persistSoon(); }
        if (this.pendingSectTrial && unavailableGate(this.pendingSectTrial.returnPosition?.mapId)) { this.pendingSectTrial.returnPosition = { ...at }; this.persistSoon(); }
      }
    }
    if (!this.position || typeof this.position !== 'object'
      || (this.position.mapId !== 'field_test' && !Object.prototype.hasOwnProperty.call(TILED_MAPS, this.position.mapId))
      || !Number.isFinite(this.position.x) || !Number.isFinite(this.position.y)) this.position = null;
    if (!this.flags || typeof this.flags !== 'object' || Array.isArray(this.flags)) this.flags = {};
    this.flags = Object.fromEntries(Object.entries(this.flags).filter(([key, value]) => flagKey(key) && typeof value === 'boolean'));
    // 只补旧档缺失的容器；已有异常记录保留，由宗门消费者暂停交易。
    if (this.sectGrowthState && typeof this.sectGrowthState === 'object' && !Array.isArray(this.sectGrowthState)) {
      const state = this.sectGrowthState;
      const candidate = { ...state,
        donationBatches: Object.prototype.hasOwnProperty.call(state, 'donationBatches') ? state.donationBatches : {},
        settledTransactions: Object.prototype.hasOwnProperty.call(state, 'settledTransactions') ? state.settledTransactions : {},
      };
      if (validSectGrowthState(candidate)) this.sectGrowthState = candidate;
    }
    if (!this.skills || typeof this.skills !== 'object') this.skills = {};
    if (!this.skillGifted || typeof this.skillGifted !== 'object') this.skillGifted = {};
    if (!this.skillMastery || typeof this.skillMastery !== 'object') this.skillMastery = {};
    if (!this.inventory || typeof this.inventory !== 'object') this.inventory = {};
    if (!this.equip || typeof this.equip !== 'object') this.equip = {};
    if (!this.quests || typeof this.quests !== 'object') this.quests = {};
    if (!Array.isArray(this.learnedRecipes)) this.learnedRecipes = [];
    this.learnedRecipes = [...new Set(this.learnedRecipes.filter(id => typeof id === 'string' && !!RECIPES[id]))];
    if (featureEnabled('lifeSkillCurve') && LIFE_SKILLS) {
      const before = JSON.stringify([this.alchemyLevel, this.alchemyExp, this.talismanLevel, this.talismanExp, this.forgingLevel, this.forgingExp]);
      const alchemy = normalizeLifeSkillProgress(LIFE_SKILLS, this.alchemyLevel, this.alchemyExp);
      const talisman = normalizeLifeSkillProgress(LIFE_SKILLS, this.talismanLevel, this.talismanExp);
      const forging = normalizeLifeSkillProgress(LIFE_SKILLS, this.forgingLevel, this.forgingExp);
      this.alchemyLevel = alchemy.level; this.alchemyExp = alchemy.exp;
      this.talismanLevel = talisman.level; this.talismanExp = talisman.exp;
      this.forgingLevel = forging.level; this.forgingExp = forging.exp;
      if (before !== JSON.stringify([this.alchemyLevel, this.alchemyExp, this.talismanLevel, this.talismanExp, this.forgingLevel, this.forgingExp])) this.persistSoon();
    } else {
      const alchemyLevel = Number(this.alchemyLevel), alchemyExp = Number(this.alchemyExp);
      this.alchemyLevel = Number.isFinite(alchemyLevel) ? Math.min(ALCHEMY_RULES.alchemyExp.maxLevel, Math.max(1, Math.floor(alchemyLevel))) : 1;
      this.alchemyExp = Number.isFinite(alchemyExp) ? Math.max(0, Math.floor(alchemyExp)) : 0;
    }
    if (!this.pillQualities || typeof this.pillQualities !== 'object' || Array.isArray(this.pillQualities)) this.pillQualities = {};
    for (const id of Object.keys(this.pillQualities)) {
      if (!ITEMS[id] || this.count(id) <= 0) delete this.pillQualities[id];
      else this.pillQualities[id] = this.pillQualityCounts(id);
    }
    if (!Array.isArray(this.visitedMaps)) this.visitedMaps = [];
    if (!Array.isArray(this.talismanQuickSlots)) this.talismanQuickSlots = Array.from({ length: HOTBAR_SLOTS.length }, () => null);
    if (featureEnabled('talismanCraft')) {
      const before = JSON.stringify([this.talisman, this.talismanUse, this.visitedMaps, this.pillQualities, this.talismanQuickSlots]);
      this.talismanQuickSlots = Array.from({ length: HOTBAR_SLOTS.length }, (_, index) => {
        const slot = this.talismanQuickSlots[index];
        return slot && ['talisman_fire', 'talisman_guard', 'talisman_return', 'talisman_gather'].includes(slot.item)
          && ['low', 'mid', 'high', 'supreme'].includes(slot.quality) ? { item: slot.item, quality: slot.quality } : null;
      });
      this.talisman = normalizeTalismanSave(this.talisman);
      this.talismanUse = normalizeTalismanUseState(this.talismanUse, gameNow());
      this.visitedMaps = [...new Set((Array.isArray(this.visitedMaps) ? this.visitedMaps : []).filter(id => typeof id === 'string' && Object.prototype.hasOwnProperty.call(TILED_MAPS, id)))];
      if (this.position && !this.visitedMaps.includes(this.position.mapId) && TILED_MAPS[this.position.mapId]) this.visitedMaps.push(this.position.mapId);
      for (const id of Object.keys(this.inventory)) if (this.qualityEnabled(id) && this.count(id) > 0) this.pillQualities[id] = this.qualityCounts(id);
      if (before !== JSON.stringify([this.talisman, this.talismanUse, this.visitedMaps, this.pillQualities, this.talismanQuickSlots])) this.persistSoon();
    }
    if (!this.gatherRespawnAt || typeof this.gatherRespawnAt !== 'object' || Array.isArray(this.gatherRespawnAt)) this.gatherRespawnAt = {};
    this.gatherRespawnAt = Object.fromEntries(Object.entries(this.gatherRespawnAt).filter(([, at]) => typeof at === 'number' && Number.isFinite(at) && at > 0));
    if (!Array.isArray(this.openedChests)) this.openedChests = [];
    this.openedChests = [...new Set(this.openedChests.filter(key => typeof key === 'string' && key.length > 0))];
    if (!isBrewSession(this.pendingAlchemy, this.learnedRecipes)) this.pendingAlchemy = null;
    for (const st of Object.values(this.quests)) {
      if (!st || typeof st !== 'object') continue;
      if (!st.kills || typeof st.kills !== 'object') st.kills = {};
      if (!st.crafted || typeof st.crafted !== 'object' || Array.isArray(st.crafted)) st.crafted = {};
      st.crafted = Object.fromEntries(Object.entries(st.crafted).map(([id, n]) => [id, Number.isFinite(Number(n)) ? Math.max(0, Math.floor(Number(n))) : 0]));
    }
    if (typeof this.job !== 'string') this.job = '';
    if (!Number.isFinite(this.classVersion)) this.classVersion = 0;
    if (!count(this.questRewardVersion)) this.questRewardVersion = 0;
    if (!Array.isArray(this.classRewardClaims)) this.classRewardClaims = [];
    this.classRewardClaims = [...new Set(this.classRewardClaims.filter(id => typeof id === 'string' && !!classDef(id)))];
    this.classRefundSp = Math.max(0, Math.floor(Number(this.classRefundSp) || 0));
    if (typeof this.rootElement !== 'string') this.rootElement = '';
    if (!Array.isArray(this.completedTrials)) this.completedTrials = [];
    this.completedTrials = [...new Set(this.completedTrials.filter(id => typeof id === 'string' && id.length > 0))];
    const attempt = this.pendingSectTrial;
    if (!attempt || typeof attempt.id !== 'string' || !QUESTS[`q_sect_${attempt.id.replace('trial_sect_', '')}`]
      || !attempt.returnPosition || !TILED_MAPS[attempt.returnPosition.mapId]
      || !Number.isFinite(attempt.returnPosition.x) || !Number.isFinite(attempt.returnPosition.y)) this.pendingSectTrial = null;
    if (this.pendingSectTrial) {
      const at = sectTrialReturnPosition(this.pendingSectTrial.returnPosition);
      if (at !== this.pendingSectTrial.returnPosition) { this.pendingSectTrial.returnPosition = at; this.persistSoon(); }
    } else if (this.position) {
      const at = sectTrialReturnPosition(this.position);
      if (at !== this.position) { this.position = at; this.persistSoon(); }
    }
    if (!this.skillCooldowns || typeof this.skillCooldowns !== 'object' || Array.isArray(this.skillCooldowns)) this.skillCooldowns = {};
    this.skillCooldowns = Object.fromEntries(Object.entries(this.skillCooldowns).filter(([id, cd]) => SKILLS[id] && cd
      && Number.isFinite(cd.readyAt) && cd.readyAt > gameNow() && Number.isFinite(cd.total) && cd.total > 0));
    if (typeof this.spTipShown !== 'boolean') this.spTipShown = false;
    if (!Array.isArray(this.tutorialsSeen)) this.tutorialsSeen = [];
    this.tutorialsSeen = [...new Set(this.tutorialsSeen.filter(id => typeof id === 'string' && id.length > 0))];
    const contribution = Number(this.sectContribution);
    this.sectContribution = Number.isFinite(contribution) ? Math.max(0, Math.floor(contribution)) : 0;
    if (typeof this.sectDailyContributionDay !== 'string') this.sectDailyContributionDay = '';
    if (!Array.isArray(this.sectDailyContributionClaims)) this.sectDailyContributionClaims = [];
    this.sectDailyContributionClaims = [...new Set(this.sectDailyContributionClaims.filter(id => typeof id === 'string' && id.length > 0))];
    if (typeof this.dailyQuestResetDay !== 'string') this.dailyQuestResetDay = '';
    if (!this.dailyQuestCompletions || typeof this.dailyQuestCompletions !== 'object' || Array.isArray(this.dailyQuestCompletions)) this.dailyQuestCompletions = {};
    for (const [sect, ids] of Object.entries(this.dailyQuestCompletions)) {
      this.dailyQuestCompletions[sect] = Array.isArray(ids) ? [...new Set(ids.filter(id => typeof id === 'string' && QUESTS[id]?.daily && QUESTS[id].sect === sect))] : [];
    }
    this.age = Number.isFinite(Number(this.age)) ? Math.max(LIFESPAN.startAge, Number(this.age)) : LIFESPAN.startAge;
    this.ageUpdatedAt = Number.isFinite(Number(this.ageUpdatedAt)) && this.ageUpdatedAt > 0 ? Math.min(gameNow(), this.ageUpdatedAt) : gameNow();
    if (typeof this.seclusionDay !== 'string') this.seclusionDay = '';
    this.seclusionYearsToday = Math.max(0, Math.floor(Number(this.seclusionYearsToday) || 0));
    if (!Array.isArray(this.seclusionHistory)) this.seclusionHistory = [];
    this.seclusionHistory = this.seclusionHistory.filter(x => x && Number.isFinite(x.at) && x.years > 0).slice(-20);
    if (!Array.isArray(this.hotbar)) this.hotbar = [];
    while (this.hotbar.length < HOTBAR_SLOTS.length) this.hotbar.push(null);
    if (this.hotbar.length > HOTBAR_SLOTS.length) this.hotbar.length = HOTBAR_SLOTS.length;
    if (!Array.isArray(this.buffs)) this.buffs = [];
    const now = gameNow();
    this.buffs = this.buffs.filter(b => b && typeof b.expireAt === 'number' && b.expireAt > now);
    // 两轴分别修复，不从旧 flags/任务推断；有限整数裁剪，损坏值回退配表初值。
    const { daoHeart, morality, moralVersion } = this;
    for (const key of ['daoHeart', 'morality'] as const) {
      const value = this[key], rule = MORAL_STATE[key];
      this[key] = typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value)
        ? Math.min(rule.max, Math.max(rule.min, value)) : rule.initial;
    }
    if (!count(this.moralVersion)) this.moralVersion = 0;
    this.moralVersion = Math.max(this.moralVersion, MORAL_VERSION);
    if (daoHeart !== this.daoHeart || morality !== this.morality || moralVersion !== this.moralVersion) this.persistSoon();
  }

  get lifespanCap() { return Number((LIFESPAN.cap as Record<string, number>)[this.realm.id] ?? LIFESPAN.cap.mortal); }
  get remainingLife() { return Math.max(0, this.lifespanCap - this.age); }
  advanceAge(now = gameNow()) {
    const elapsed = Math.max(0, now - this.ageUpdatedAt);
    this.age += elapsed / 3600000 * LIFESPAN.agePerRealHour;
    this.ageUpdatedAt = now;
  }

  /**
   * 已完成 q_breakthrough / q_fox、但存档里没有对应功法时补发。
   * 和任务交付走同一条 grantSkill：不检查前置。
   */
  backfillQuestSkills() {
    let changed = false;
    for (const qid of QUEST_SKILL_BACKFILL) {
      if (this.quests[qid]?.state !== 'done') continue;
      for (const s of QUESTS[qid]?.rewards.skills ?? []) {
        const def = SKILLS[s.id];
        // 转职后的刷新不可再把灵气弹/其他宗门的旧任务技能塞回快捷栏。
        if (this.job && (!def || CLASS_RULES.replaceCommonSkills.includes(s.id) || !this.ownsSkill(def))) continue;
        if (this.grantSkill(s.id, s.level)) changed = true;
      }
    }
    return changed;
  }

  backfillQuestRecipes() {
    let changed = false;
    for (const [id, st] of Object.entries(this.quests)) {
      if (st?.state === 'done' && QUESTS[id]) changed = this.grantQuestRecipes(QUESTS[id]).length > 0 || changed;
    }
    // 教学回春丹必须先于 craft 目标可用；旧进行中存档同样补上。
    if (this.quests.q_alchemy_intro?.state === 'active') changed = this.grantRecipe('recipe_hp_pill') || changed;
    return changed;
  }

  skillLevel(id: string) { return this.trialSkills[id]?.level ?? this.skills?.[id] ?? 0; }

  /** 御剑是筑基奖励能力；领取与使用的境界均读取 skills.req.realm。 */
  skillRealmMet(def: SkillDef) {
    const required = def.req?.realm;
    if (required === undefined) return true;
    const realm = typeof required === 'string' ? REALMS.find((r: { id: string }) => r.id === required) : undefined;
    return !!realm && this.level >= realm.levelMin;
  }

  /** 已筑基缺技的旧档也补齐一次；不花 SP，不把已有技能再次升级。 */
  ensureSwordRideGranted() {
    const def = SKILLS.sword_ride;
    if (!def || typeof def.req?.realm !== 'string' || !this.skillRealmMet(def) || (this.skills.sword_ride ?? 0) > 0) return false;
    const unlocked = REALMS.some((realm: { levelMax: number; reward?: { unlock?: string[] } }) =>
      realm.levelMax < this.level && realm.reward?.unlock?.includes(def.id));
    return unlocked && this.grantSkill(def.id, 1);
  }

  beginTrialSkills(grants: { id: string; level: number; charges?: number; durationMs?: number }[]) {
    this.endTrialSkills();
    this.trialHotbarBefore = [...this.hotbar];
    for (const [index, grant] of grants.entries()) if (SKILLS[grant.id]) {
      this.trialSkills[grant.id] = { level: grant.level, charges: grant.charges, durationMs: grant.durationMs };
      const slot = this.hotbar.findIndex((id, i) => i > 0 && id === null);
      this.hotbar[slot >= 0 ? slot : Math.min(index + 1, this.hotbar.length - 1)] = grant.id;
    }
  }
  endTrialSkills() {
    for (const id of Object.keys(this.trialSkills)) {
      this.buffs = this.buffs.filter(b => b.id !== id);
      delete this.skillCooldowns[id];
    }
    if (this.trialHotbarBefore) this.hotbar = [...this.trialHotbarBefore];
    this.trialSkills = {}; this.trialHotbarBefore = null;
  }
  canCastSkill(def: SkillDef) { return !!this.trialSkills[def.id] || this.ownsSkill(def); }
  trialSkillCharges(id: string) { return this.trialSkills[id]?.charges; }
  consumeTrialSkill(id: string) {
    const skill = this.trialSkills[id];
    if (skill?.charges !== undefined) { if (skill.charges <= 0) return false; skill.charges--; }
    return true;
  }
  trialSkillDuration(id: string) { return this.trialSkills[id]?.durationMs; }

  get classSkills() { return skillsForClass(this.job); }
  get sect() { return classDef(this.job)?.sect ?? ''; }
  /** 未拜入仅有通用技能资格；宗门和转职阶段均须与当前职业匹配。 */
  ownsSkill(def: SkillDef) {
    if (isCheatSkillsUnlocked()) return true;
    // 表内保留天剑二转分类；筑基自动获得的移动能力不以拜宗/转职为前提。
    if (def.id === 'sword_ride') return this.skillRealmMet(def);
    if (!this.job) return def.sect === null && def.job === 0;
    const c = classDef(this.job);
    return !!c && def.sect === c.sect && def.job === c.job;
  }

  /**
   * 拜入只能发生一次。通用技能的付费等级退回一转点池，原热键换成本宗入门技；
   * 旧档同样清理残留通用技能，以删除记录保证退点幂等，保留本宗自定义键位。
   */
  advanceClass(job: string, initializeSectRank = true): boolean {
    const c = classDef(job);
    if (!c || (!this.job && this.level < classMinLevel(c)) || (this.job && this.job !== c.id)) return false;
    if (!classEntryEnabled(c) && !this.job && this.quests[c.joinQuest]?.state !== 'done') return false;
    const firstJoin = !this.job;
    const legacyRewards = this.questRewardVersion < QUEST_REWARD_VERSION;
    const migrating = this.classVersion < 2;
    let changed = firstJoin || migrating;
    this.job = c.id;
    if (initializeSectRank && firstJoin && this.sectRank === null) this.sectRank = SECT_RANKS.rules.initialRank;
    const entry = classEntrySkill(c);
    // 也遍历配置中的通用技能，清掉只有键位、熟练度或冷却而没有等级的旧档残留。
    for (const id of new Set([...Object.keys(this.skills), ...CLASS_RULES.replaceCommonSkills])) {
      if (id === 'sword_ride') continue;
      const def = SKILLS[id], common = CLASS_RULES.replaceCommonSkills.includes(id);
      if (!common && !((firstJoin || migrating) && def?.sect && def.sect !== c.sect)) continue;
      if (!(id in this.skills || id in this.skillGifted || id in this.skillMastery || id in this.skillCooldowns
        || this.hotbar.includes(id) || this.buffs.some(buff => buff.id === id))) continue;
      if (common) this.classRefundSp += Math.max(0, this.skillLevel(id) - (this.skillGifted[id] ?? 0)) * (def?.spCost ?? 1);
      delete this.skills[id]; delete this.skillGifted[id]; delete this.skillMastery[id]; delete this.skillCooldowns[id];
      const slot = common ? this.hotbar.indexOf(id) : -1;
      this.hotbar = this.hotbar.map((bound, index) => {
        // 入门技已有绑定时迁到原通用技能的槽位，避免同一技能占两格。
        if (slot >= 0 && entry && bound === entry.id) return null;
        return bound === id ? (index === slot ? entry?.id ?? null : null) : bound;
      });
      this.buffs = this.buffs.filter(buff => buff.id !== id);
      changed = true;
    }
    for (const gift of classGiftSkills(c, legacyRewards)) changed = this.grantSkill(gift.id, gift.level) || changed;
    if (!this.classRewardClaims.includes(c.id)) {
      const robe = classRobe(c);
      if (robe && this.equip.robe !== robe) {
        if (!firstJoin && c.sect === CLASS_RULES.unjoinedSkillSect) {
          // 老剑徒的穿戴保持原样，未领过的宗门道袍补进背包。
          if (this.count(robe) <= 0) this.addItem(robe, 1);
        } else {
          if (this.count(robe) > 0) this.removeItem(robe, 1);
          if (this.equip.robe) this.addItem(this.equip.robe, 1);
          this.equip.robe = robe;
        }
      }
      this.classRewardClaims.push(c.id); changed = true;
    }
    this.classVersion = Math.max(this.classVersion, 2);
    if (changed) this.persistSoon();
    return true;
  }

  /** 正式入宗事实优先；仅旧奖励版本的已交妖狐档继承原天剑身份。 */
  backfillClass(initializeSectRank = true): boolean {
    const state = () => JSON.stringify({ job: this.job, classVersion: this.classVersion, questRewardVersion: this.questRewardVersion, classRefundSp: this.classRefundSp,
      skills: this.skills, gifted: this.skillGifted, mastery: this.skillMastery, hotbar: this.hotbar,
      cooldowns: this.skillCooldowns, buffs: this.buffs, claims: this.classRewardClaims, equip: this.equip, inventory: this.inventory, rank: this.sectRank });
    const before = state();
    const formal = classDef(this.job) ?? Object.keys(this.quests).map(classForQuest)
      .find(candidate => candidate && this.quests[candidate.joinQuest]?.state === 'done');
    const legacy = !formal && this.questRewardVersion < QUEST_REWARD_VERSION && this.quests.q_fox?.state === 'done'
      ? classDef('tianjian_disciple') : undefined;
    // 旧妖狐交付已经入宗；保留衣着和本宗技能/键位，道袍按已有职业补进背包。
    if (legacy) {
      this.job = legacy.id;
      if (initializeSectRank && this.sectRank === null) this.sectRank = SECT_RANKS.rules.initialRank;
    }
    const c = formal ?? legacy;
    if (c) this.advanceClass(c.id, initializeSectRank);
    this.questRewardVersion = Math.max(this.questRewardVersion, QUEST_REWARD_VERSION);
    const changed = before !== state();
    // 旧档尚未交妖狐也登记新规则，以后交付、刷新不能被再次当成旧入宗事实。
    if (changed) this.persistSoon();
    return changed;
  }

  /** 被动心法加成。只统计 type=passive，buff 的 speed/jump 不走这里。 */
  passiveBonus(key: string) {
    let v = 0;
    for (const [id, lv] of Object.entries(this.skills ?? {})) {
      if (!(lv > 0)) continue;
      const def = SKILLS[id];
      if (!def || def.type !== 'passive' || !this.ownsSkill(def)) continue;
      v += skillNumber(def, key, lv);
    }
    return v;
  }

  buffActive(id: string) { return this.buffs.some(b => b.id === id && b.expireAt > gameNow()); }
  /** 布尔效果不经过 skillNumber，避免 invisible 被当成数字 0。 */
  hasBuffEffect(key: string) {
    return this.buffs.some(buff => {
      const def = SKILLS[buff.id];
      return buff.expireAt > gameNow() && !!def && this.canCastSkill(def) && this.skillLevel(def.id) > 0 && def.effects[key] === true;
    });
  }
  buffBonus(key: string) {
    let value = 0;
    const counted = new Set<string>();
    for (const buff of this.buffs) {
      if (buff.expireAt <= gameNow() || counted.has(buff.id)) continue;
      const def = SKILLS[buff.id], level = this.skillLevel(buff.id);
      if (!def || !this.canCastSkill(def) || level <= 0) continue;
      counted.add(buff.id); value += skillNumber(def, key, level);
    }
    return value;
  }
  effectBonus(key: string) { return this.passiveBonus(key) + this.buffBonus(key); }
  buffRemaining(id: string) {
    const b = this.buffs.find(x => x.id === id);
    return b ? Math.max(0, b.expireAt - gameNow()) : 0;
  }

  /**
   * 当前速度 / 跳跃点数。基础 100，加上装备 stats，轻身术生效时再把 perLevel×等级加进去（加法，不是倍率）。
   */
  currentMovePoints() {
    let speed = (GROWTH.base.speed ?? 100) + this.equipSum('speed') + this.statBonus('speed');
    let jump = (GROWTH.base.jump ?? 100) + this.equipSum('jump') + this.statBonus('jump');
    speed += this.effectBonus('speed'); jump += this.effectBonus('jump');
    return { speed, jump };
  }

  spEarned(job: number) { return spEarnedFor(this.level, job, !!this.job) + (job === CLASS_RULES.advanceJob ? this.classRefundSp : 0); }
  spSpent(job: number) {
    let n = 0;
    for (const [id, lv] of Object.entries(this.skills)) {
      const def = SKILLS[id];
      if (!def || def.job !== job || !this.ownsSkill(def)) continue;
      const gifted = Math.min(this.skillGifted[id] ?? 0, lv);
      n += Math.max(0, lv - gifted) * (def.spCost ?? 1);
    }
    return n;
  }
  spLeftFor(job: number) { return Math.max(0, this.spEarned(job) - this.spSpent(job)); }

  skillCap(def: SkillDef) {
    let cap = def.maxLevel;
    const mastery = this.skillMastery[def.id] ?? 0;
    if (def.masteryToCap > 0 && mastery >= def.masteryToCap) cap += SKILL_RULES.masteryCapBonus ?? 0;
    return cap;
  }

  /** 玩家自己加点才检查前置和等级上限。 */
  prereqMet(def: SkillDef) {
    const band = spBand(def.job);
    if (band && this.level < band.min) return false;
    const c = classDef(this.job);
    if (c && this.level < classMinLevel(c)) return false;
    const req = def.req;
    if (!req) return true;
    for (const [k, v] of Object.entries(req)) {
      if (k === 'level' || k === 'reqLevel') {
        if (this.level < Number(v)) return false;
      } else if (k === 'realm') {
        const realm = REALMS.find((r: { id: string; levelMin: number }) => r.id === v);
        if (realm ? this.level < realm.levelMin : this.realm?.id !== v) return false;
      } else if (k === 'item') {
        if (this.count(String(v)) <= 0) return false;
      } else if (this.skillLevel(k) < Number(v)) return false;
    }
    return true;
  }

  reqText(def: SkillDef) {
    const req = def.req;
    const parts: string[] = [];
    const minLevel = Math.max(spBand(def.job)?.min ?? 0, classDef(this.job) ? classMinLevel(classDef(this.job)!) : 0);
    if (this.level < minLevel) parts.push(`角色 ${minLevel}级`);
    for (const [k, v] of Object.entries(req ?? {})) {
      if (k === 'level' || k === 'reqLevel') {
        if (this.level < Number(v)) parts.push(`角色 ${v}级`);
      } else if (k === 'realm') {
        const realm = REALMS.find((r: { id: string; name?: string; levelMin: number }) => r.id === v);
        if (realm && this.level < realm.levelMin) parts.push(realm.name ?? String(v));
      } else if (k === 'item') {
        if (this.count(String(v)) <= 0) parts.push(ITEMS[String(v)]?.name ?? String(v));
      } else if (this.skillLevel(k) < Number(v)) parts.push(`${SKILLS[k]?.name ?? k} ${v}级`);
    }
    return parts.join('、');
  }

  /**
   * 直接学会到至少 level 级。任务奖励用这条，不检查前置。
   * 新给的等级记进 skillGifted，升级不花技能点。
   */
  grantSkill(id: string, level: number, force = false) {
    const forced = force && isCheatEnabled();
    if (!SKILLS[id] || (!this.ownsSkill(SKILLS[id]) && !forced) || !(level > 0)) return false;
    // 作弊赠技写永久等级，不应被试炼的临时技能遮住；普通赠技沿用现有规则。
    const cur = forced || isCheatSkillsUnlocked() || id === 'sword_ride' ? this.skills[id] ?? 0 : this.skillLevel(id);
    if (level <= cur) return false;
    this.skillGifted[id] = (this.skillGifted[id] ?? 0) + (level - cur);
    this.skills[id] = level;
    this.autoBind(id);
    return true;
  }

  /** 窗口与实际学习入口共用的检查，不改变技能、点数或存档。 */
  checkSkillPoint(id: string): { ok: true } | { ok: false; reason: 'missing' | 'locked' | 'max' | 'req' | 'sp'; req?: string } {
    const def = SKILLS[id];
    if (!def) return { ok: false, reason: 'missing' };
    if (!this.skillsUnlocked || !this.ownsSkill(def)) return { ok: false, reason: 'locked' };
    if (this.skillLevel(id) >= this.skillCap(def)) return { ok: false, reason: 'max' };
    if (!this.prereqMet(def)) return { ok: false, reason: 'req', req: this.reqText(def) };
    const cost = def.spCost ?? 1;
    if (this.spLeftFor(def.job) < cost) return { ok: false, reason: 'sp' };
    return { ok: true };
  }

  addSkillPoint(id: string) {
    const result = this.checkSkillPoint(id);
    if (!result.ok) return result;
    const def = SKILLS[id];
    this.skills[id] = this.skillLevel(id) + 1;
    if (def.type !== 'passive') this.autoBind(id);
    this.persistSoon();
    return result;
  }

  skillMpCost(id: string) {
    const def = SKILLS[id];
    const lv = this.skillLevel(id);
    if (!def || lv <= 0) return 0;
    const raw = Math.max(0, skillNumber(def, 'mpCost', lv));
    const reduce = Math.min(0.9, Math.max(0, this.passiveBonus('mpCostReduce')));
    return raw * (1 - reduce);
  }

  skillAttackRate(def: SkillDef) {
    return def.effects.attackSpeedAffectsCooldown ? 1 + Math.max(0, this.effectBonus('attackSpeedRatio')) : 1;
  }
  skillRecoverMs(id: string) {
    const def = SKILLS[id];
    return def ? actOf(def).recoverMs / this.skillAttackRate(def) : 0;
  }
  /** 0 独立冷却仍受后摇约束，快捷栏也沿用原来的后摇遮罩。 */
  skillCooldownMs(id: string) {
    const def = SKILLS[id], lv = this.skillLevel(id);
    if (!def || lv <= 0) return 0;
    return Math.max(0, skillNumber(def, 'cooldownMs', lv), actOf(def).recoverMs) / this.skillAttackRate(def);
  }

  addMastery(id: string, hits = 1) {
    const def = SKILLS[id];
    if (!def?.masteryPerHit || hits <= 0) return;
    const cap = def.masteryToCap > 0 ? def.masteryToCap : Infinity;
    this.skillMastery[id] = Math.min(cap, (this.skillMastery[id] ?? 0) + def.masteryPerHit * hits);
  }

  /** 主动和增益放进快捷栏。default:A 优先占 A 格，被动不占格。 */
  autoBind(id: string) {
    const def = SKILLS[id];
    if (!def || !this.ownsSkill(def) || def.type === 'passive' || this.skillLevel(id) <= 0) return;
    if (this.hotbar.includes(id)) return;
    let idx = -1;
    const label = def.key?.match(/^default:(.+)$/)?.[1];
    if (label) {
      const i = HOTBAR_SLOTS.findIndex(s => s.label === label);
      if (i >= 0 && !this.hotbar[i]) idx = i;
    }
    if (idx < 0) idx = this.hotbar.findIndex(s => !s);
    if (idx >= 0) this.hotbar[idx] = id;
  }

  bindHotbar(slot: number, id: string | null) {
    if (slot < 0 || slot >= this.hotbar.length) return false;
    if (id) {
      const def = SKILLS[id];
      if (!def || !this.ownsSkill(def) || def.type === 'passive' || this.skillLevel(id) <= 0) return false;
      this.hotbar = this.hotbar.map(s => (s === id ? null : s));
    }
    this.hotbar[slot] = id;
    this.persistSoon();
    return true;
  }
}

